// ---------- 合成効果音（Web Audio API のみ。外部音源なし） ----------
let audioCtx: AudioContext | null = null;
let sfxMuted = false;

function getCtx(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (!audioCtx) {
    const w = window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext };
    const C = w.AudioContext ?? w.webkitAudioContext;
    if (!C) return null;
    try { audioCtx = new C(); } catch (_e) { return null; }
  }
  if (audioCtx.state === "suspended") { void audioCtx.resume(); }
  return audioCtx;
}

function tone(c: AudioContext, at: number, freq: number, dur: number, type: OscillatorType, vol: number, slideTo?: number): void {
  const o = c.createOscillator();
  const g = c.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, at);
  if (slideTo !== undefined) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), at + dur);
  g.gain.setValueAtTime(0.0001, at);
  g.gain.exponentialRampToValueAtTime(vol, at + 0.012);
  g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
  o.connect(g);
  g.connect(c.destination);
  o.start(at);
  o.stop(at + dur + 0.03);
}

function noise(c: AudioContext, at: number, dur: number, vol: number, cutoff: number, cutoffEnd?: number): void {
  const len = Math.max(1, Math.floor(c.sampleRate * dur));
  const buf = c.createBuffer(1, len, c.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
  const src = c.createBufferSource();
  src.buffer = buf;
  const f = c.createBiquadFilter();
  f.type = "lowpass";
  f.frequency.setValueAtTime(cutoff, at);
  if (cutoffEnd !== undefined) f.frequency.exponentialRampToValueAtTime(Math.max(30, cutoffEnd), at + dur);
  const g = c.createGain();
  g.gain.setValueAtTime(0.0001, at);
  g.gain.exponentialRampToValueAtTime(vol, at + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
  src.connect(f);
  f.connect(g);
  g.connect(c.destination);
  src.start(at);
  src.stop(at + dur + 0.03);
}

function sfx(name: SfxName): void {
  if (sfxMuted) return;
  const c = getCtx();
  if (!c) return;
  const t = c.currentTime + 0.01;
  switch (name) {
    case "atk":
      noise(c, t, 0.12, 0.35, 2400, 300);
      tone(c, t, 220, 0.16, "square", 0.12, 70);
      break;
    case "def":
      tone(c, t, 880, 0.35, "triangle", 0.16);
      tone(c, t + 0.01, 1320, 0.3, "sine", 0.07);
      break;
    case "heal":
      [523, 659, 784, 1047].forEach((f: number, i: number) => tone(c, t + i * 0.07, f, 0.22, "sine", 0.13));
      break;
    case "meme":
      tone(c, t, 330, 0.12, "square", 0.08, 660);
      tone(c, t + 0.12, 660, 0.14, "square", 0.08, 990);
      break;
    case "chaos":
      tone(c, t, 600, 0.4, "sawtooth", 0.09, 90);
      tone(c, t, 613, 0.4, "sawtooth", 0.06, 95);
      noise(c, t + 0.05, 0.25, 0.12, 900, 200);
      break;
    case "collapse":
      noise(c, t, 1.0, 0.4, 1800, 80);
      tone(c, t, 110, 1.0, "sawtooth", 0.14, 32);
      tone(c, t + 0.15, 75, 0.8, "sine", 0.22, 28);
      break;
    case "win":
      [523, 659, 784].forEach((f: number, i: number) => tone(c, t + i * 0.12, f, 0.2, "square", 0.09));
      tone(c, t + 0.36, 1047, 0.6, "square", 0.1);
      tone(c, t + 0.36, 784, 0.6, "triangle", 0.08);
      break;
    case "lose":
      [392, 370, 349].forEach((f: number, i: number) => tone(c, t + i * 0.22, f, 0.24, "triangle", 0.13));
      tone(c, t + 0.66, 330, 0.9, "triangle", 0.13, 160);
      break;
    case "start":
      tone(c, t, 440, 0.1, "square", 0.09);
      tone(c, t + 0.09, 880, 0.22, "square", 0.09);
      break;
    case "whisper":
      tone(c, t, 55, 1.4, "sine", 0.22, 41);
      tone(c, t, 82, 1.4, "sawtooth", 0.05, 61);
      tone(c, t + 0.2, 1661, 0.9, "sine", 0.03, 1244);
      tone(c, t + 0.45, 1108, 0.8, "sine", 0.025, 830);
      noise(c, t, 1.2, 0.18, 600, 60);
      break;
    case "pass":
      tone(c, t, 500, 0.08, "sine", 0.08, 380);
      break;
    case "impact":
      noise(c, t, 0.18, 0.5, 3200, 120);
      tone(c, t, 95, 0.26, "sine", 0.38, 38);
      break;
    case "crit":
      noise(c, t, 0.26, 0.6, 4200, 90);
      tone(c, t, 80, 0.4, "sine", 0.42, 30);
      tone(c, t + 0.02, 1500, 0.14, "square", 0.07, 600);
      tone(c, t + 0.09, 1900, 0.12, "square", 0.05, 900);
      break;
    case "hype":
      tone(c, t, 300, 0.28, "sawtooth", 0.07, 1200);
      tone(c, t + 0.22, 880, 0.18, "square", 0.08);
      tone(c, t + 0.3, 1320, 0.22, "square", 0.06);
      break;
    case "awaken":
      tone(c, t, 60, 0.7, "sawtooth", 0.12, 260);
      noise(c, t, 0.6, 0.25, 400, 5000);
      tone(c, t + 0.5, 1047, 0.35, "square", 0.08);
      tone(c, t + 0.5, 784, 0.35, "triangle", 0.08);
      break;
    case "draw":
      noise(c, t, 0.07, 0.12, 6000, 2500);
      tone(c, t + 0.02, 1200, 0.07, "triangle", 0.06, 1800);
      break;
    case "chain":
      [660, 880, 1175, 1568].forEach((f: number, i: number) => tone(c, t + i * 0.045, f, 0.09, "square", 0.06));
      break;
    case "heat":
      tone(c, t, 70, 0.9, "sawtooth", 0.12, 180);
      noise(c, t, 0.8, 0.22, 300, 3500);
      tone(c, t + 0.6, 1397, 0.3, "square", 0.05);
      break;
    case "stun":
      [0, 1, 2, 3].forEach((i: number) => tone(c, t + i * 0.09, i % 2 ? 900 : 1200, 0.09, "sine", 0.09));
      noise(c, t, 0.1, 0.25, 2500, 400);
      break;
    case "debuff":
      tone(c, t, 600, 0.35, "square", 0.07, 150);
      tone(c, t + 0.05, 611, 0.35, "square", 0.05, 155);
      break;
    case "regen":
      [784, 988, 1175].forEach((f: number, i: number) => tone(c, t + i * 0.1, f, 0.4, "sine", 0.08));
      break;
    case "chapter":
      tone(c, t, 49, 2.0, "sine", 0.3, 40);
      tone(c, t, 98, 1.8, "sawtooth", 0.07, 80);
      noise(c, t, 1.6, 0.3, 5000, 100);
      tone(c, t + 0.4, 392, 1.2, "triangle", 0.08);
      tone(c, t + 0.4, 587, 1.2, "triangle", 0.06);
      break;
    case "slam":
      noise(c, t, 0.22, 0.55, 1800, 60);
      tone(c, t, 130, 0.3, "square", 0.18, 45);
      tone(c, t + 0.06, 65, 0.3, "sine", 0.3, 30);
      break;
    case "quake":
      noise(c, t, 1.3, 0.45, 700, 40);
      tone(c, t, 41, 1.3, "sine", 0.3, 30);
      tone(c, t + 0.3, 233, 0.6, "sawtooth", 0.06, 60);
      break;
    default:
      break;
  }
}

