function stageScene(st: Stage): Scene {
  return { tag: `${st.code}${st.boss ? "（ボス戦）" : ""}`, title: st.area, lines: st.intro, img: st.boss || st.chapter === 2 ? "collapse" : "hero", eldritch: st.chapter === 2, pic: st.pic };
}
function scenesBefore(si: number, stageOnly: boolean): Scene[] {
  const st = STAGES[si];
  if (!st) return [];
  const prev = STAGES[si - 1];
  const out: Scene[] = [];
  if (!stageOnly && (!prev || prev.chapter !== st.chapter)) out.push(st.chapter === 1 ? CH1_INTRO : CH2_INTRO);
  out.push(stageScene(st));
  return out;
}
function scenesAfter(si: number): { scenes: Scene[]; next: number | null } {
  const st = STAGES[si];
  if (!st) return { scenes: [ENDING], next: null };
  const nx = STAGES[si + 1];
  const out: Scene[] = [{ tag: `${st.code} クリア`, title: `${st.enemy}を撃破`, lines: st.win, img: "hero", eldritch: st.chapter === 2 }];
  if (!nx) { out.push(ENDING); return { scenes: out, next: null }; }
  if (nx.chapter !== st.chapter) out.push(CH1_END);
  return { scenes: [...out, ...scenesBefore(si + 1, false)], next: si + 1 };
}
function firstOf(ch: 1 | 2): number { return Math.max(0, STAGES.findIndex((s: Stage) => s.chapter === ch)); }

function cardOf(key: string): CardDef {
  const d = ALL_CARDS.find((c: CardDef) => c.key === key);
  if (!d) throw new Error("unknown card " + key);
  return d;
}
function rand(n: number): number { return Math.floor(Math.random() * n); }
function pick<T>(a: T[]): T { return a[rand(a.length)] as T; }
function shuffle<T>(a: T[]): T[] {
  const r = a.slice();
  for (let i = r.length - 1; i > 0; i--) { const j = rand(i + 1); const t = r[i] as T; r[i] = r[j] as T; r[j] = t; }
  return r;
}
function other(s: Side): Side { return s === "p" ? "c" : "p"; }
function has(g: Game, k: ModKind): boolean { return g.mods.some((m: Mod) => m.kind === k); }
function costShift(g: Game): number { return (has(g, "costUp") ? 1 : 0) - (has(g, "costDown") ? 1 : 0) + (has(g, "stars") ? g.star : 0); }
function synergyCut(g: Game, side: Side, d: CardDef): number {
  const f = g[side];
  let n = f.disc;
  if (d.key === "omatase" && (f.lastKey === "kokoko" || f.lastKey === "mitoke")) n += 2;
  if (d.key === "combo" && f.chainKind === "atk" && f.chain >= 1) n += 1;
  return n;
}
function costOf(g: Game, d: CardDef, side: Side): number { return Math.max(0, d.cost + costShift(g) - synergyCut(g, side, d)); }
function bump(f: Fighter, n: number): void { f.heat = Math.min(HEAT_MAX, f.heat + n); }
function nextCount(g: Game): number { return 1 + g.boost + (STAGES[g.stage]?.boss && g.round % 2 === 0 ? 1 : 0); }
function handLimit(g: Game, side: Side): number {
  if (side === "c") return HAND_MAX;
  if (has(g, "san")) return 3;
  return g.san < 25 ? 3 : g.san < 50 ? 4 : HAND_MAX;
}
function sanDelta(g: Game, n: number): void {
  if (g.chapter !== 2 || n === 0) return;
  g.san = Math.max(0, Math.min(100, g.san + n));
  note(g, `SAN ${n > 0 ? "+" : ""}${n}（現在${g.san}）`);
  if (g.san <= 0) {
    const d = hurtNonLethal(g, "p", 10);
    g.san = 30;
    note(g, `発狂！ ファッ！？ 田所浩二に${d}ダメージ。SANは30まで戻った`);
  }
}
function healRaw(g: Game, side: Side, n: number): void { const f = g[side]; f.hp = Math.min(f.max, f.hp + n); }
function restoreTile(g: Game): string | null {
  const dead = g.tiles.filter((t: Tile) => !t.alive);
  if (dead.length === 0) return null;
  const t = pick(dead);
  t.alive = true;
  return t.name;
}
function morphHand(g: Game, side: Side, key: string): void {
  const f = g[side];
  if (f.hand.length === 0) return;
  const i = rand(f.hand.length);
  const x = f.hand[i];
  if (!x) return;
  const from = cardOf(x.key).name;
  f.hand[i] = { uid: x.uid, key };
  note(g, `${f.name}の「${from}」が「${cardOf(key).name}」に変わった`);
}
function giveCard(g: Game, side: Side, key: string): void {
  const f = g[side];
  if (f.hand.length >= handLimit(g, side)) return;
  g.uid++;
  f.hand.push({ uid: g.uid, key });
  note(g, `${f.name}の手札に「${cardOf(key).name}」が流れ着いた`);
}
function energyMax(g: Game): number { return BASE_ENERGY + (has(g, "energyUp") ? 1 : 0); }

function cloneF(f: Fighter): Fighter { return { ...f, hand: f.hand.slice(), deck: f.deck.slice() }; }
function cloneG(g: Game): Game {
  return { ...g, p: cloneF(g.p), c: cloneF(g.c), mods: g.mods.map((m: Mod) => ({ ...m })), tiles: g.tiles.map((t: Tile) => ({ ...t })), log: g.log.slice(), clog: g.clog.slice(), last: g.last ? { ...g.last } : null };
}

function log(g: Game, who: Who, text: string): void {
  g.uid++;
  g.log = [{ id: g.uid, who, text }, ...g.log].slice(0, 80);
}
function note(g: Game, text: string): void {
  g.uid++;
  const line: LogLine = { id: g.uid, who: "col", text };
  g.clog = [line, ...g.clog].slice(0, 80);
}

function newDeck(g: Game): Inst[] {
  const out: Inst[] = [];
  (g.chapter === 2 ? ALL_CARDS : CARDS).forEach((c: CardDef) => { for (let i = 0; i < c.copies; i++) { g.uid++; out.push({ uid: g.uid, key: c.key }); } });
  return shuffle(out);
}

function draw(g: Game, side: Side, n: number, force: boolean): number {
  const f = g[side];
  if (!force && has(g, "noDraw")) { log(g, side, `${f.name}は下北沢の濃霧でドローできない（前見えねぇ）`); return 0; }
  let got = 0;
  for (let i = 0; i < n; i++) {
    if (f.hand.length >= handLimit(g, side)) break;
    if (f.deck.length === 0) { f.deck = newDeck(g); log(g, "sys", `${f.name}の山札が再構築された（淫夢は終わらない。当たり前だよなぁ？）`); }
    const x = f.deck.shift();
    if (x) { f.hand.push(x); got++; }
  }
  return got;
}

function addMod(g: Game, kind: ModKind, turns: number, label: string): void {
  const m = g.mods.find((x: Mod) => x.kind === kind);
  if (m) m.turns = Math.max(m.turns, turns); else g.mods.push({ kind, turns, label });
}

function hurtNonLethal(g: Game, side: Side, n: number): number {
  const f = g[side];
  if (f.hp <= 0) return 0;
  const before = f.hp;
  f.hp = Math.max(1, f.hp - n);
  return before - f.hp;
}

// 崩壊ダメージ：脆弱で×1.5、シールドが半分まで肩代わり
function colHurt(g: Game, side: Side, n: number): number {
  const f = g[side];
  let v = f.vuln > 0 ? Math.round(n * 1.5) : n;
  const ab = Math.min(f.shield, Math.ceil(v / 2));
  f.shield -= ab;
  v -= ab;
  return hurtNonLethal(g, side, v);
}
function applyStun(g: Game, side: Side, by: Side): void {
  const f = g[side];
  if (f.shield >= 10) { log(g, by, `└ ${f.name}は胸板（シールド${f.shield}）でスタンを受け止めた。効いてないんだよなぁ`); return; }
  f.stun = 1;
  log(g, by, `└ ${f.name}をスタン（次ラウンド気力-2）。ファッ！？`);
}
function useHeat(g: Game, side: Side, kind: "kiai" | "awaken"): boolean {
  const f = g[side];
  if (kind === "kiai") {
    if (f.heat < 3) return false;
    f.heat -= 3; f.energy += 1;
    log(g, side, `${f.name}の迫真の気合（熱量3）：気力+1。ほらいくどー！`);
    return true;
  }
  if (f.heat < HEAT_MAX || f.awaken) return false;
  f.heat = 0; f.awaken = true;
  log(g, side, `${f.name}が野獣覚醒（熱量MAX）：次の攻撃×2＆シールド貫通。見とけよ見とけよ〜`);
  return true;
}

function destroyTile(g: Game): string | null {
  const alive = g.tiles.filter((t: Tile) => t.alive);
  if (alive.length === 0) return null;
  const t = pick(alive);
  t.alive = false;
  return t.name;
}

