function evList(g: Game): CollapseEvent[] { return g.chapter === 2 ? EVENTS2 : EVENTS; }

function collapse(g: Game, count: number, cause: string): void {
  for (let i = 0; i < count; i++) {
    g.collapses++;
    const list = evList(g);
    const ev = list[g.fc] ?? pick(list);
    g.fc = rand(list.length);
    const tile = destroyTile(g);
    note(g, `崩壊#${g.collapses}（${cause}）${tile ? `［${tile}が崩落］` : ""}【${ev.name}】${ev.desc}（${pick(HOT_LINES)}）`);
    ev.run(g);
    if (g.chapter === 2) sanDelta(g, -3);
    g.last = { name: ev.name, desc: ev.desc, tile, img: ev.img };
    if (!g.endless && g.tiles.every((t: Tile) => !t.alive)) {
      g.endless = true;
      note(g, "世界完全崩壊。これもうわかんねぇな。終焉モード突入：以降の全ダメージ×1.5（本番はこれから）");
    }
  }
}

function dealDamage(g: Game, from: Side, base: number, pierce: boolean): { dealt: number; blocked: number } {
  const a = g[from];
  const d = g[other(from)];
  let v = base + a.power;
  v *= a.mult;
  a.mult = 1;
  let pr = pierce;
  if (a.awaken) { v *= 2; pr = true; a.awaken = false; log(g, from, "└ 野獣覚醒！ 眼光が盾を貫く"); }
  if (a.weak > 0) v *= 0.6;
  if (d.vuln > 0) v *= 1.5;
  if (d.vuln > 0 && d.stun > 0) v += 5;
  if (has(g, "halfAtk")) v *= 0.5;
  if (has(g, "dmgDouble")) v *= 2;
  if (g.endless) v *= 1.5;
  if (has(g, "nameless")) v *= 0.5 + Math.random();
  if (has(g, "mad")) { const n = hurtNonLethal(g, from, 3); if (n > 0) log(g, from, `狂気で${a.name}も${n}ダメージ`); }
  if (d.parry > 0) { d.parry = 0; v *= 0.5; const rf = hurtNonLethal(g, from, Math.round(v)); log(g, other(from), `└ 受け流し！ 半減して${rf}跳ね返した（いいよ！こいよ！）`); }
  let dmg = Math.max(1, Math.round(v));
  let blocked = 0;
  if (!pr && d.shield > 0) { blocked = Math.min(d.shield, dmg); d.shield -= blocked; dmg -= blocked; }
  d.hp = Math.max(0, d.hp - dmg);
  return { dealt: dmg, blocked };
}

function healSide(g: Game, side: Side, amt: number): string {
  const f = g[side];
  if (has(g, "healInvert")) { const n = hurtNonLethal(g, side, amt); return `回復が反転して${n}ダメージ！`; }
  const a = has(g, "healBoost") ? Math.round(amt * 1.5) : amt;
  const before = f.hp;
  f.hp = Math.min(f.max, f.hp + a);
  return `HP+${f.hp - before}`;
}

