function playCard(g: Game, side: Side, uid: number): void {
  const f = g[side];
  const o = g[other(side)];
  const idx = f.hand.findIndex((i: Inst) => i.uid === uid);
  if (idx < 0) return;
  const [inst] = f.hand.splice(idx, 1);
  if (!inst) return;
  const d = cardOf(inst.key);
  f.energy -= costOf(g, d, side);
  f.disc = 0;
  const prevKey = f.lastKey;
  const prevKind = f.chainKind;
  if (d.key === "assouda") { f.chain = Math.max(1, f.chain + 1); if (!f.chainKind) f.chainKind = "meme"; }
  else if (f.chainKind === d.kind) f.chain++;
  else { f.chain = 1; f.chainKind = d.kind; }
  f.lastKey = d.key;
  f.played++;
  const ch = f.chain;
  const cb = ch >= 2 ? ch - 1 : 0;
  g.playSeq++;
  g.playKind = d.kind;
  log(g, side, `${f.name}の【${d.name}】`);
  if (cb > 0) { bump(f, 1); log(g, side, `└ ${ch}連鎖（${KIND_LABEL[f.chainKind ?? d.kind]}）！ 熱量+1　${pick(HIT_LINES)}`); }
  if (ch >= 3) { f.disc = 1; log(g, side, "└ 迫真コンボ：次のカード気力-1"); }
  let bonus = d.kind === "atk" ? cb * 4 : 0;
  const hit = (base: number, pierce: boolean): void => {
    const r = dealDamage(g, side, base + bonus, pierce);
    bonus = 0;
    log(g, side, `└ ${o.name}に${r.dealt}ダメージ${r.blocked > 0 ? `（シールドで${r.blocked}防いだ）` : ""}${r.dealt >= 18 ? `　${pick(HIT_LINES)}` : r.dealt === 0 ? "　効いてないんだよなぁ" : ""}`);
  };
  switch (d.key) {
    case "fah": hit(10, false); break;
    case "abaren": hit(17, false); break;
    case "karate": hit(15, true); if (prevKind === "atk" && o.hp > 0) applyStun(g, other(side), side); break;
    case "kuso": hit(14 + (f.hp < o.hp ? 10 : 0), false); break;
    case "combo": hit(25 + ch * 5, false); break;
    case "omatase": hit(24, false); break;
    case "doutei": hit(f.hp <= 35 ? 24 : 8, false); break;
    case "iiyo": f.shield += 12; log(g, side, "└ シールド+12"); if (f.shield >= 20) { bump(f, 1); log(g, side, "└ 分厚い胸板：熱量+1"); } break;
    case "oudou": f.shield += 16; f.regen = Math.max(f.regen, 2); log(g, side, `└ シールド+16、${healSide(g, side, 4)}、再生2R`); break;
    case "sai24": log(g, side, `└ ${healSide(g, side, 18 + (prevKey === "nuwa" ? 10 : 0))}${prevKey === "nuwa" ? "（ぬわ→24歳の黄金リレー）" : ""}`); break;
    case "nuwa": { const h = healSide(g, side, 9); const n = draw(g, side, 1, false); log(g, side, `└ ${h}、${n}枚ドロー`); break; }
    case "iizo": { const h = healSide(g, side, 7); f.mult = Math.min(3, f.mult * 1.3); log(g, side, `└ ${h}、次の攻撃×${f.mult.toFixed(2)}`); break; }
    case "yarimasu": f.mult = Math.min(3, f.mult * 1.6); if (prevKind === "atk") bump(f, 1); log(g, side, `└ 次の攻撃×${f.mult.toFixed(2)}${prevKind === "atk" ? "、褒められて熱量+1" : ""}`); break;
    case "mitoke": f.power += 4; log(g, side, `└ 攻撃力+4（合計+${f.power}）`); break;
    case "senpai": o.weak = 2; if (prevKind === "meme") o.vuln = Math.max(o.vuln, 2); log(g, side, `└ ${o.name}は2ラウンド弱体化${prevKind === "meme" ? "＋脆弱2R（やめてくださいよ本当に！）" : ""}`); break;
    case "dame": {
      o.shield = 0;
      let msg = `└ ${o.name}のシールド消滅`;
      if (o.hand.length > 0) { const [x] = o.hand.splice(rand(o.hand.length), 1); if (x) msg += `、【${cardOf(x.key).name}】を捨てさせた`; }
      log(g, side, msg);
      if (o.vuln > 0 && o.hp > 0) applyStun(g, other(side), side);
      break;
    }
    case "ossu": { const n = draw(g, side, 2, false); log(g, side, `└ ${n}枚ドロー`); break; }
    case "metya": hit(8, false); if (o.hp > 0) collapse(g, 1, "あーもう滅茶苦茶だよ"); break;
    case "yane": f.shield += 8; g.boost += 1; log(g, side, "└ シールド+8、ラウンド終了時の崩壊+1"); break;
    case "bb": {
      collapse(g, 2, "BB劇場");
      const n = colHurt(g, other(side), 12);
      log(g, side, `└ 世界崩壊×2、${o.name}に崩壊ダメージ${n}`);
      break;
    }
    case "upstream": {
      const n = f.hand.length;
      f.hand = [];
      const got = draw(g, side, n + 1, true);
      log(g, side, `└ 手札${n}枚が流され、${got}枚ドロー`);
      collapse(g, 1, "upstream");
      break;
    }
    case "daijoubu": f.weak = 0; f.vuln = 0; log(g, side, `→ ${healSide(g, side, 10)}、弱体・脆弱解除`); break;
    case "nanda": hit(13 + (o.shield > 0 ? 7 : 0), false); break;
    case "horahora": for (let i = 0; i < 4; i++) { if (o.hp > 0) hit(5 + ch, false); } break;
    case "sasshi": { f.shield += 6; const n = draw(g, side, 1, false); log(g, side, `→ シールド+6、${n}枚ドロー`); break; }
    case "jaken": addMod(g, "dmgDouble", 2, "ダメージ×2"); g.boost += 1; log(g, side, "→ 全ダメージ×2（次のラウンドまで）、崩壊+1"); break;
    case "nandemo": {
      if (o.hand.length > 0 && f.hand.length < handLimit(g, side)) {
        const [x] = o.hand.splice(rand(o.hand.length), 1);
        if (x) { f.hand.push(x); log(g, side, `→ ${o.name}の「${cardOf(x.key).name}」を奪った`); }
      } else log(g, side, "→ 何も奪えなかった");
      break;
    }
    case "meiyari": hit(20, false); if (side === "p") sanDelta(g, -6); break;
    case "kyuu114": hit(30, false); if (side === "p") sanDelta(g, -10); break;
    case "shoki24": { const h = healSide(g, side, 6); if (side === "p") sanDelta(g, 20); log(g, side, `→ ${h}、正気を取り戻す`); break; }
    case "iaia": hit(10, false); if (side === "p") sanDelta(g, -4); if (o.hp > 0) collapse(g, 1, "いあ いあ"); break;
    case "kyushin": { f.shield += 18; f.stun = 0; g.mods = g.mods.filter((m: Mod) => m.kind !== "nameless" && m.kind !== "mad"); log(g, side, "→ シールド+18、名状しがたき呪いを祓った"); break; }
    case "kokoko": f.mult = Math.min(3, f.mult * 1.4); f.shield += 4; log(g, side, `→ こ↑こ↓に陣取った。次の攻撃×${f.mult.toFixed(2)}、シールド+4`); break;
    case "aiten": { const s = Math.floor(o.shield / 2); o.shield -= s; f.shield += s; g.boost += 1; log(g, side, `→ 開いてたシールドを${s}奪った。次の崩壊+1`); break; }
    case "atarimae": hit(16 + (o.weak > 0 && o.vuln > 0 ? 14 : o.weak > 0 || o.vuln > 0 ? 8 : 0), false); break;
    case "yohou": { g.fc = rand(evList(g).length); bump(f, 1); log(g, side, `→ 崩壊予報を書き換えた：次は【${evList(g)[g.fc]?.name ?? "？"}】、熱量+1`); break; }
    case "sundome": hit(6, false); if (o.hp > 0) applyStun(g, other(side), side); break;
    case "mugicha": { f.regen = Math.max(f.regen, 3); const c = f.vuln > 0 ? "脆弱" : f.weak > 0 ? "弱体" : ""; if (f.vuln > 0) f.vuln = 0; else f.weak = 0; log(g, side, `→ 再生3R${c ? `、${c}解除` : ""}。冷えてますよ〜`); break; }
    case "assouda": { const n = draw(g, side, 1, false); log(g, side, `→ 連鎖継続（${ch}）、${n}枚ドロー。あっ、そうだ（何が）`); break; }
    case "miroyo": o.vuln = Math.max(o.vuln, 2); log(g, side, `→ ${o.name}は脆弱2R（被ダメ×1.5）`); break;
    case "gankou": { const h = f.heat; f.heat = 0; log(g, side, `→ 熱量${h}を解放`); hit(12 + h * 6, h >= 4); break; }
    case "hakkiri": { const n = draw(g, side, 1, false); f.mult = Math.min(3, f.mult * 1.3); log(g, side, `→ ${n}枚ドロー、次の攻撃×${f.mult.toFixed(2)}`); break; }
    case "yattaze": { const h = healSide(g, side, 12); f.power += 1; log(g, side, `→ ${h}、攻撃力+1。やったぜ。`); break; }
    case "ichiban": hit(18, false); if (side === "p") sanDelta(g, -3); break;
    case "wakan": o.weak = 2; log(g, side, `→ ${o.name}は2ラウンド弱体（これもうわかんねぇな）`); if (side === "p") sanDelta(g, -5); if (o.hp > 0) collapse(g, 1, "これもうわかんねぇな"); break;
    case "atsui": hit(12 + f.heat * 3, false); break;
    case "hiyashi": { const h = healSide(g, side, 8); bump(f, 1); log(g, side, `→ ${h}、熱量+1。冷えてますよ〜`); break; }
    case "ganko2": o.vuln = Math.max(o.vuln, 2); applyStun(g, other(side), side); log(g, side, `→ ${o.name}は脆弱2R＋スタン`); break;
    case "kintore": f.shield += 8; f.bank += 1; log(g, side, "→ シールド+8、筋肉貯金：次ラウンド気力+1（ベンチプレス114kg）"); break;
    case "kaunta": f.parry = 1; log(g, side, "→ 受け流しの構え。いいよ！こいよ！"); break;
    case "hoshii": { const n = Math.min(2, o.heat); o.heat -= n; bump(f, n); let m = `→ ${o.name}の熱量${n}を奪った`; if (o.awaken) { o.awaken = false; f.awaken = true; m += "、覚醒まで奪った（お前のものが欲しいとか？）"; } log(g, side, m); break; }
    case "dechau": { const s2 = hurtNonLethal(g, side, 8); log(g, side, `→ 自分に${s2}ダメージ。本当に出ちゃうよ！`); hit(22, f.hp <= 35); break; }
    case "yattane": if (f.heat >= 2) { f.heat -= 2; f.weak = 0; f.vuln = 0; log(g, side, `→ 熱量2を変換：${healSide(g, side, 14)}、状態解除。ヤッタネ！`); } else log(g, side, `→ ${healSide(g, side, 5)}（熱が足りない）`); break;
    case "iced": { o.stun = Math.max(o.stun, 1); log(g, side, `→ ${o.name}はアイスティーで眠気（スタン確定）、${healSide(g, side, 6)}`); break; }
    case "ikisugi": hit(19, false); bump(f, 1); break;
    case "aa": hit(12 + (prevKind === "atk" ? 6 : 0), false); break;
    case "akushiro": { f.energy += 1; const s2 = hurtNonLethal(g, side, 4); log(g, side, `→ 気力+1、自分に${s2}ダメージ。あくしろよ`); break; }
    case "kuiaratame": { f.weak = 0; f.vuln = 0; f.stun = 0; o.mult = 1; log(g, side, `→ ${healSide(g, side, 10)}、状態解除、${o.name}の攻撃倍率リセット（†悔い改めて†）`); break; }
    case "foo": { const h = healSide(g, side, 8); bump(f, 1); log(g, side, `→ ${h}、熱量+1。Foo↑`); break; }
    case "kuchiake": {
      o.mult = 1;
      let msg = `→ ${o.name}の攻撃倍率リセット`;
      if (o.hand.length > 0) { const [x] = o.hand.splice(rand(o.hand.length), 1); if (x) msg += `、【${cardOf(x.key).name}】を捨てさせた`; }
      log(g, side, msg);
      break;
    }
    case "taikai": { f.shield += 9; const n = draw(g, side, 1, false); log(g, side, `→ シールド+9、${n}枚ドロー`); break; }
    case "yarimasu2": f.mult = Math.min(3, f.mult * 2); bump(f, 1); log(g, side, `→ 次の攻撃×${f.mult.toFixed(2)}、熱量+1。やりますねぇ！やりますねぇ！`); break;
    case "doyagao": o.weak = Math.max(o.weak, 2); f.power += 1; log(g, side, `→ ${o.name}は2ラウンド弱体、攻撃力+1（ドヤ顔）`); break;
    case "baka": hit(15, f.hp <= o.hp); break;
    case "sannin": for (let i = 0; i < 3; i++) { if (o.hp > 0) hit(9, false); } break;
    case "heeki": { f.vuln = 0; f.shield += 4; log(g, side, `→ ${healSide(g, side, 6)}、脆弱解除、シールド+4`); break; }
    case "baan": {
      const n = colHurt(g, other(side), 10);
      const s2 = colHurt(g, side, 5);
      log(g, side, `→ ${o.name}に崩壊ダメージ${n}、自分も${s2}（追突）`);
      if (o.hp > 0) collapse(g, 1, "バァン！（大破）");
      break;
    }
    case "bacche": { const n = Math.min(2, o.heat); o.heat -= n; log(g, side, `→ ${healSide(g, side, 7)}、${o.name}の熱量-${n}`); break; }
    case "kanashii": { const n = Math.min(2, o.power); o.power -= n; log(g, side, `→ ${o.name}の攻撃力-${n}（悲しいなぁ）`); break; }
    case "owari": g.mods = []; o.shield = 0; log(g, side, `→ 地形効果を全解除、${o.name}のシールド0。閉廷！`); hit(12, false); break;
    case "takuya": f.shield += 14; f.parry = 1; log(g, side, "→ シールド+14、受け流しの構え（戦車にひかれても死なない）"); break;
    case "menkyo": { const n = Math.min(1, o.heat); o.heat -= n; bump(f, n); const k = draw(g, side, 1, false); log(g, side, `→ ${o.name}の熱量${n}を奪い、${k}枚ドロー`); break; }
    case "tekozura": hit(14 + (o.stun > 0 ? 10 : 0), false); break;
    case "shoggoth": hit(26, false); sanDelta(g, -5); break;
    case "mazui": f.shield += 10; o.power = Math.max(0, o.power - 3); log(g, side, `→ シールド+10、${o.name}の次ターン攻撃力-3（まずいですよ！）`); break;
    case "oraora": hit(16, f.shield >= 15); break;
    case "yurusane": hit(18, false); collapse(g, 1, "もう許さねぇ"); f.hp = Math.max(1, f.hp - 6); log(g, side, `→ 怒りの代償：自分のHP-6、世界崩壊+1`); break;
    default: break;
  }
  if (cb > 0 && o.hp > 0) {
    if (d.kind === "def") { f.shield += cb * 4; log(g, side, `└ 連鎖ボーナス：シールド+${cb * 4}`); }
    else if (d.kind === "heal") log(g, side, `└ 連鎖ボーナス：${healSide(g, side, cb * 3)}`);
    else if (d.kind === "meme") { const n = draw(g, side, 1, false); log(g, side, `└ 連鎖ボーナス：${n}枚ドロー`); }
    else if (d.kind === "chaos") { const n = colHurt(g, other(side), cb * 4); bump(f, 1); log(g, side, `└ 連鎖ボーナス：${o.name}に崩壊ダメージ${n}、熱量さらに+1`); }
  }
}

function checkEnd(g: Game): boolean {
  if (g.p.hp > 0 && g.c.hp > 0) return false;
  g.result = g.p.hp <= 0 && g.c.hp <= 0 ? "draw" : g.p.hp <= 0 ? "lose" : "win";
  g.phase = "end";
  log(g, "sys", g.result === "win" ? `${g.c.name}を撃破！ やりますねぇ！` : g.result === "lose" ? (g.chapter === 1 ? "田所浩二（24歳、学生）、崩壊する淫夢に沈む…ファッ！？" : "田所浩二、名状しがたきものに呑まれる…まずいですよ！") : "相打ち。世界ごと終わった（あーもう滅茶苦茶だよ）");
  return true;
}

function startRound(g: Game): void {
  g.round++;
  log(g, "sys", `― 第${g.round}ラウンド ―　${pick(ROUND_CALLS)}`);
  if (has(g, "poison")) {
    const a = colHurt(g, "p", 5);
    const b = colHurt(g, "c", 5);
    log(g, "sys", `灼熱の屋上（日焼けしすぎ）で${g.p.name} -${a}、${g.c.name} -${b}（シールドが半分肩代わり）`);
  }
  (["p", "c"] as Side[]).forEach((s: Side) => {
    const f = g[s];
    if (f.regen > 0 && f.hp > 0) { log(g, s, `${f.name}の再生：${healSide(g, s, 4)}`); f.regen--; }
  });
  if (has(g, "stars")) { g.star = pick([-1, 1]); log(g, "sys", `星辰のゆらぎ：全カードのコスト${g.star > 0 ? "+1" : "-1"}`); }
  draw(g, "p", 2, false);
  draw(g, "c", 2, false);
  (["p", "c"] as Side[]).forEach((s: Side) => {
    const f = g[s];
    f.energy = energyMax(g);
    if (f.stun > 0) { f.energy = Math.max(1, f.energy - 2); f.stun = 0; log(g, s, `${f.name}はスタン中（暴れんなよ…）：気力${f.energy}`); }
    if (f.bank > 0) { f.energy += f.bank; log(g, s, `${f.name}の筋肉貯金：気力+${f.bank}（筋トレの成果）`); f.bank = 0; }
  });
  g.phase = "player";
}

function endRound(g: Game): Game {
  g.mods = g.mods.map((m: Mod) => ({ ...m, turns: m.turns - 1 })).filter((m: Mod) => m.turns > 0);
  g.p.weak = Math.max(0, g.p.weak - 1);
  g.c.weak = Math.max(0, g.c.weak - 1);
  g.p.parry = 0; g.c.parry = 0;
  g.p.vuln = Math.max(0, g.p.vuln - 1);
  g.c.vuln = Math.max(0, g.c.vuln - 1);
  const lim = handLimit(g, "p");
  if (g.p.hand.length > lim) { const lost = g.p.hand.splice(lim); note(g, `正気が足りず、手札${lost.length}枚を手放した`); }
  const bossExtra = STAGES[g.stage]?.boss && g.round % 2 === 0 ? 1 : 0;
  const n = 1 + g.boost + bossExtra;
  g.boost = 0;
  collapse(g, n, `第${g.round}ラウンド終了`);
  if (!checkEnd(g)) startRound(g);
  return g;
}

function passTurn(g: Game, side: Side): void {
  const f = g[side];
  const n = draw(g, side, 1, false);
  f.hp = Math.min(f.max, f.hp + 3);
  log(g, side, `${f.name}はパス（${pick(PASS_LINES)}）：${n}枚ドロー、HP+3`);
}

function endTurn(g: Game, side: Side): void {
  const f = g[side];
  if (f.played === 0) { passTurn(g, side); bump(f, 1); }
  else if (f.energy > 0) { bump(f, 1); log(g, side, `${f.name}は気力${f.energy}を余らせた：熱量+1（溜め）`); }
  f.chain = 0; f.chainKind = null; f.lastKey = null; f.played = 0; f.disc = 0;
}

function estimate(g: Game, key: string): number {
  const f = g.c;
  const o = g.p;
  switch (key) {
    case "fah": return 10;
    case "abaren": return 17;
    case "karate": return 15;
    case "kuso": return f.hp < o.hp ? 24 : 14;
    case "combo": return 25;
    case "omatase": return 24;
    case "doutei": return f.hp <= 35 ? 24 : 8;
    case "metya": return 8;
    case "nanda": return o.shield > 0 ? 20 : 13;
    case "horahora": return 20;
    case "meiyari": return 20;
    case "kyuu114": return 30;
    case "iaia": return 10;
    case "atarimae": return o.weak > 0 ? 24 : 16;
    case "ichiban": return 18;
    case "sundome": return 6;
    case "gankou": return 12 + f.heat * 6;
    case "atsui": return 12 + f.heat * 3;
    case "shoggoth": return 26;
    case "dechau": return 22;
    case "ikisugi": return 19;
    case "aa": return f.chainKind === "atk" ? 18 : 12;
    case "baka": return 15;
    case "sannin": return 27;
    case "owari": return 12;
    case "tekozura": return o.stun > 0 ? 24 : 14;
    case "oraora": return 16;
    case "yurusane": return 18;
    default: return 0;
  }
}

interface Scored { i: Inst; s: number }
function cpuScore(g: Game, i: Inst): number {
  const f = g.c;
  const o = g.p;
  const d = cardOf(i.key);
  const chainOn = f.chain > 0 && (f.chainKind === d.kind || d.key === "assouda");
  const cb = chainOn ? f.chain : 0;
  const est = estimate(g, i.key);
  let s = 0;
  if (est > 0) {
    let v = (est + (d.kind === "atk" ? cb * 4 : 0) + f.power) * f.mult * (f.awaken ? 2 : 1) * (f.weak > 0 ? 0.6 : 1) * (o.vuln > 0 ? 1.5 : 1);
    if (has(g, "halfAtk")) v *= 0.5;
    if (has(g, "dmgDouble")) v *= 2;
    const pierce = i.key === "karate" || (i.key === "baka" && f.hp <= o.hp) || f.awaken || (i.key === "gankou" && f.heat >= 4);
    s = pierce ? v : Math.max(1, v - o.shield * 0.7);
    if (o.parry > 0) s *= 0.4;
    if (i.key === "dechau" && f.hp <= 12) s = -5;
    if (v >= o.hp + (pierce ? 0 : o.shield)) s += 100;
    if (i.key === "gankou" && f.heat < 3) s -= 10;
    if ((i.key === "sundome" || i.key === "karate") && o.shield < 10 && o.stun === 0) s += 6;
  } else if (d.kind === "heal") s = has(g, "healInvert") ? -10 : (f.max - f.hp) / 3 + (f.vuln > 0 || f.weak > 0 ? 4 : 0);
  else if (d.kind === "def") s = 6 + (f.hp < f.max * 0.5 ? 8 : 0) - f.shield / 4;
  else if (d.kind === "meme") {
    if (i.key === "yarimasu" || i.key === "yarimasu2" || i.key === "kokoko" || i.key === "hakkiri") s = f.mult < 2 && f.hand.some((x: Inst) => x.uid !== i.uid && estimate(g, x.key) > 0) ? 9 : 2;
    else if (i.key === "senpai" || i.key === "miroyo") s = o.vuln > 0 && o.weak > 0 ? 1 : 10;
    else if (i.key === "dame") s = 4 + o.shield / 2 + (o.vuln > 0 ? 6 : 0);
    else s = 6;
  } else s = 4 + rand(4);
  if (chainOn) s += 5;
  return s;
}

function cpuAct(g: Game): Game {
  const f = g.c;
  const afford = (): Inst[] => f.hand.filter((i: Inst) => costOf(g, cardOf(i.key), "c") <= f.energy);
  if (f.heat >= HEAT_MAX && !f.awaken && afford().some((i: Inst) => estimate(g, i.key) > 0 && i.key !== "gankou")) useHeat(g, "c", "awaken");
  if (f.heat >= 3 && f.heat < HEAT_MAX && f.hand.some((i: Inst) => costOf(g, cardOf(i.key), "c") === f.energy + 1 && cpuScore(g, i) > 8)) useHeat(g, "c", "kiai");
  const scored: Scored[] = afford().map((i: Inst) => ({ i, s: cpuScore(g, i) })).sort((a: Scored, b: Scored) => b.s - a.s);
  const top = scored[0];
  if (top && top.s > 3 && f.played < 6) {
    playCard(g, "c", top.i.uid);
    const tl = ENEMY_LINES[STAGES[g.stage]?.code ?? ""];
    if (tl && g.c.hp > 0 && Math.random() < 0.45) log(g, "c", `${g.c.name}「${pick(tl)}」`);
    checkEnd(g);
    return g;
  }
  endTurn(g, "c");
  if (!checkEnd(g)) g.phase = "collapse";
  return g;
}

function intentOf(g: Game): string {
  const f = g.c;
  const heat = f.heat >= HEAT_MAX ? "／熱量MAX：覚醒の気配（まずいですよ！）" : f.heat >= 3 ? `／熱量${f.heat}：気合で気力+1あり` : "";
  if (f.awaken) return "覚醒済み：次の攻撃×2・貫通が来る。受け流しか「お前のものが欲しいとか？」で潰せ";
  const aff = f.hand.filter((i: Inst) => costOf(g, cardOf(i.key), "c") <= f.energy);
  const atk = aff.map((i: Inst) => ({ i, e: estimate(g, i.key) })).filter((x: { i: Inst; e: number }) => x.e > 0).sort((a: { i: Inst; e: number }, b: { i: Inst; e: number }) => b.e - a.e)[0];
  if (atk) return `攻撃予告：【${cardOf(atk.i.key).name}】約${atk.e + f.power}ダメージ${atk.e + f.power >= 20 ? "（受け流し・シールドで迎え撃て）" : ""}${heat}`;
  if (aff.length > 0) return `${KIND_LABEL[cardOf((aff[0] as Inst).key).kind]}の気配（攻めどき。見とけよ見とけよ〜）${heat}`;
  return `様子見の構え（しょうがねぇなぁ）${heat}`;
}
const STAGE_TIPS: Record<string, string> = {
  "1-1": "戦術：序盤は筋トレで気力を貯金→次ラウンドに大技。ファッ！？を連打で連鎖を稼げ",
  "1-2": "戦術：相手の大技予告が出たら受け流し。余った気力は熱量へ。いいよ！こいよ！",
  "1-3": "戦術：TDNはンアッー！の攻撃連打型。受け流し・拓也は戦車にひかれても死なないで山なり球をいなせ",
  "1-4": "戦術：大先輩はスタン中の相手に「手こずらせやがってよぉ」で+10。シールド10以上を保ってスタンを防げ",
  "1-5": "戦術（ボス）：偶数R終わりに崩壊増。野獣覚醒は「お前のものが欲しいとか？」で奪える。熱量を相手に渡すな",
  "2-1": "戦術：SANと火力のトレードオフ。強攻撃の前後に正気の24歳を挟め",
  "2-2": "戦術：弱体＋脆弱→当たり前だよなぁ？で+14。下準備してから切れ",
  "2-3": "戦術：本当に出ちゃうよ！はHP35以下で貫通。追い詰められてからが本番",
  "2-4": "戦術（最終）：熱量はヤッタネで回復にも変えられる。攻めるか耐えるか、熱の使い道を選べ",
};
const CARD_TIPS: Record<string, string> = {
  iced: "シールド無視で確定スタン", aa: "攻撃の直後で+6", baka: "HPが相手以下なら貫通", tekozura: "スタン中の相手に+10（アイスティー→手こずらせ）", yarimasu2: "大技の前に", owari: "地形効果をまとめて消す", takuya: "大技予告に合わせて", kanashii: "敵の攻撃力を削る", akushiro: "気力0。あと1足りない時に",
  karate: "攻撃の直後に出すとスタン", omatase: "こ↑こ↓か見とけよの後でコスト-2", sai24: "ぬわの後で+10", senpai: "ミーム技の後で脆弱も付く", dame: "脆弱中の相手ならスタン", atarimae: "弱体＋脆弱で+14", gankou: "熱量4以上で貫通。熱を溜めてから", atsui: "熱量が高いほど強い", combo: "攻撃連鎖の締めに", kintore: "今ラウンドを捨て、次に気力4", kaunta: "大技予告に合わせて", hoshii: "相手の熱量MAX・覚醒に刺す", dechau: "気力0。瀕死なら貫通", yattane: "熱量の使い道その3（回復）", sundome: "シールド10以上には効かない",
};
function newGame(si: number): Game {
  const st = (STAGES[si] ?? STAGES[0]) as Stage;
  const blank = (name: string, hp: number = HP_MAX): Fighter => ({ name, hp, max: hp, shield: 0, power: 0, mult: 1, weak: 0, hand: [], deck: [], energy: BASE_ENERGY, heat: 0, chain: 0, chainKind: null, lastKey: null, played: 0, disc: 0, vuln: 0, stun: 0, regen: 0, awaken: false, bank: 0, parry: 0 });
  const g: Game = {
    phase: "player", round: 0, p: blank("田所浩二"), c: blank(st.enemy, st.hp), mods: [],
    tiles: st.tiles.map((n: string) => ({ name: n, alive: true })), log: [], clog: [], boost: 0,
    endless: false, collapses: 0, result: null, last: null, uid: 0, playSeq: 0, playKind: null,
    stage: si, chapter: st.chapter, san: 100, star: 0, fc: 0,
  };
  g.fc = rand(evList(g).length);
  g.c.power = st.power;
  g.p.deck = newDeck(g);
  g.c.deck = newDeck(g);
  draw(g, "p", 3, true);
  draw(g, "c", 3, true);
  log(g, "sys", `${st.code}「${st.area}」${st.boss ? "（ボス戦）" : ""}`);
  log(g, "sys", `淫夢世界に降り立った。対戦相手：${g.c.name}。オッスお願いしまーす`);
  note(g, "世界はまだ形を保っている（今のところは）。そんな装備で大丈夫か？");
  log(g, "sys", STAGE_TIPS[st.code] ?? "戦術：何を温存し何を切るか。迫真");
  startRound(g);
  return g;
}

const ICON_POS: Record<Kind, string> = { atk: "0% 0%", def: "100% 0%", heal: "0% 100%", meme: "center", chaos: "100% 100%" };

function KindIcon({ kind, size, art }: { kind: Kind; size: number; art?: string }) {
  const theme: any = { text: "#f8e8a0", bg: "#1a1511", accent: "#d4af37", border: "#665533", fill: "#2a2511", font: "16px", secondary: "#998866", elevated: "#3a3522", weight: "bold", dataviz: { red: "#cc4444", yellow: "#ccaa44", green: "#44cc44", blue: "#4488cc", purple: "#8844cc", primary: "#d4af37", base: "#665533" }, success: "#44cc44", primary: "#d4af37", base: "#665533", warning: "#ccaa44", danger: "#cc4444" };
  const isMeme = kind === "meme";
  return (
    <span
      aria-hidden="true"
      style={{
        display: "inline-block", flex: "0 0 auto", width: size, height: size, borderRadius: 6,
        border: `1px solid ${theme.border.default}`,
        backgroundImage: `url(${art ?? (isMeme ? IMG_HERO : IMG_ICONS)})`,
        backgroundSize: art || isMeme ? "cover" : "200% 200%",
        backgroundPosition: art ? "center" : ICON_POS[kind],
        backgroundRepeat: "no-repeat",
      }}
    />
  );
}

function HpBar({ value, max, color }: { value: number; max: number; color: string }) {
  const theme: any = { text: "#f8e8a0", bg: "#1a1511", accent: "#d4af37", border: "#665533", fill: "#2a2511", font: "16px", secondary: "#998866", elevated: "#3a3522", weight: "bold", dataviz: { red: "#cc4444", yellow: "#ccaa44", green: "#44cc44", blue: "#4488cc", purple: "#8844cc", primary: "#d4af37", base: "#665533" }, success: "#44cc44", primary: "#d4af37", base: "#665533", warning: "#ccaa44", danger: "#cc4444" };
  const pct = Math.max(0, Math.min(100, (value / max) * 100));
  return (
    <div style={{ position: "relative", height: 16, borderRadius: 9999, background: theme.fill.secondary, backgroundImage: "linear-gradient(180deg, rgba(0,0,0,0.45), rgba(0,0,0,0.15))", border: "1px solid rgba(255,215,90,0.6)", boxShadow: "inset 0 2px 4px rgba(0,0,0,0.5)", overflow: "hidden" }}>
      <div style={{ position: "relative", width: `${pct}%`, height: "100%", borderRadius: 9999, background: `linear-gradient(180deg, rgba(255,255,255,0.6), ${color} 45%, ${color})`, boxShadow: `0 0 10px ${color}, 0 0 18px ${color}`, transition: "width 0.4s ease", overflow: "hidden" }}>
        <span style={{ position: "absolute", top: 0, bottom: 0, left: 0, width: "30%", background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.65), transparent)", animation: "inmuGlint 2.2s ease-in-out infinite" }} />
      </div>
    </div>
  );
}

function FighterPanel({ f, color, isPlayer, active, portrait, eerie, pops, aura }: { f: Fighter; color: string; isPlayer: boolean; active: boolean; portrait?: string; eerie?: boolean; pops: Pop[]; aura?: string }) {
  const theme: any = { text: "#f8e8a0", bg: "#1a1511", accent: "#d4af37", border: "#665533", fill: "#2a2511", font: "16px", secondary: "#998866", elevated: "#3a3522", weight: "bold", dataviz: { red: "#cc4444", yellow: "#ccaa44", green: "#44cc44", blue: "#4488cc", purple: "#8844cc", primary: "#d4af37", base: "#665533" }, success: "#44cc44", primary: "#d4af37", base: "#665533", warning: "#ccaa44", danger: "#cc4444" };
  const stat: CSSProperties = { ...theme.font.label, color: theme.text.secondary };
  const isLowHp = f.hp <= 35 && f.hp > 0;
  return (
    <div className={isLowHp ? "lowHp" : ""} style={{ border: `${active ? 3 : 2}px solid ${active ? "#ffd84a" : "rgba(224,168,0,0.6)"}`, borderRadius: 14, padding: 14, background: theme.bg.elevated, backgroundImage: `linear-gradient(160deg, color-mix(in srgb, ${color} 24%, transparent), transparent 45%, rgba(0,0,0,0.22))`, boxShadow: active ? "0 0 0 1px #8a5a00, 0 0 22px rgba(255,200,60,0.55), inset 0 1px 0 rgba(255,255,255,0.15)" : "0 6px 16px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.08)", position: "relative", ...(aura ? ({ "--aura": aura, boxShadow: `0 0 0 2px ${aura}, 0 0 14px ${aura}`, animation: "inmuAura 0.9s ease-in-out 4" } as unknown as CSSProperties) : {}) }}>
      {pops.map((p: Pop) => (
        <span key={p.id} aria-hidden="true" style={{ position: "absolute", left: `${p.x}%`, top: 16, zIndex: 3, pointerEvents: "none", ...(p.crit ? theme.font.heading1 : theme.font.heading2), fontWeight: theme.weight.semibold, whiteSpace: "nowrap", color: p.heal ? (theme.dataviz.categorical[2] ?? theme.text.success) : p.crit ? theme.dataviz.negative : theme.text.primary, textShadow: `0 2px 0 ${theme.bg.base}, 0 0 10px ${p.crit ? theme.dataviz.negative : theme.bg.base}`, animation: "inmuPop 1s ease-out forwards" }}>{p.text}{p.crit ? " CRITICAL!!" : ""}</span>
      ))}
      <div style={{ display: "flex", gap: 12, alignItems: "center", marginBottom: 8 }}>
        {isPlayer ? (
          <img src={IMG_HERO} alt="田所浩二のアバター" style={{ width: 80, height: 80, borderRadius: 14, objectFit: "cover", flex: "0 0 auto", border: "3px solid #e0a800", boxShadow: `0 0 0 2px #5a3a00, 0 0 16px ${color}` }} />
        ) : portrait ? (
          <img src={portrait} alt={`${f.name}の肖像`} style={{ width: 104, height: 104, borderRadius: 14, objectFit: "cover", flex: "0 0 auto", border: "3px solid #e0a800", boxShadow: `0 0 0 2px #5a3a00, 0 0 20px ${color}, 0 6px 14px rgba(0,0,0,0.5)`, animation: "inmuFloat 3s ease-in-out infinite", filter: eerie ? ELDRITCH_FILTER : "sepia(0.25) contrast(1.15)" }} />
        ) : (
          <div style={{ width: 56, height: 56, borderRadius: 10, flex: "0 0 auto", border: `1px solid ${theme.border.default}`, background: theme.fill.secondary, display: "flex", alignItems: "center", justifyContent: "center", ...theme.font.heading3, fontWeight: theme.weight.semibold, color: color }}>
            {f.name.slice(0, 1)}
          </div>
        )}
        <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-between", gap: 8, alignItems: "baseline", flex: "1 1 auto" }}>
          <div style={{ ...theme.font.heading3, fontWeight: 900, textShadow: `0 0 10px ${color}, 2px 2px 0 rgba(0,0,0,0.5)` }}>{f.name}{isPlayer ? "（24歳、学生）" : "（CPU）"}</div>
          <div style={{ ...theme.font.body2, fontWeight: theme.weight.semibold }}>HP {f.hp} / {f.max}</div>
        </div>
      </div>
      <HpBar value={f.hp} max={f.max} color={color} />
      <div style={{ display: "flex", flexWrap: "wrap", gap: "4px 14px", marginTop: 10 }}>
        <span style={stat}>シールド {f.shield}</span>
        <span style={stat}>攻撃力 +{f.power}</span>
        <span style={stat}>次の攻撃 ×{f.mult.toFixed(2)}</span>
        {f.weak > 0 ? <span style={{ ...theme.font.label, color: theme.text.warning }}>弱体 残り{f.weak}</span> : null}
        {f.vuln > 0 ? <span style={{ ...theme.font.label, color: theme.text.warning }}><img src={IMG_ST_VULN} alt="" style={{ width: 16, height: 16, verticalAlign: "middle", marginRight: 3 }} />脆弱 残り{f.vuln}（被ダメ×1.5）</span> : null}
        {f.stun > 0 ? <span style={{ ...theme.font.label, color: theme.text.warning }}><img src={IMG_ST_STUN} alt="" style={{ width: 16, height: 16, verticalAlign: "middle", marginRight: 3 }} />スタン（次R気力-2）</span> : null}
        {f.regen > 0 ? <span style={stat}><img src={IMG_ST_REGEN} alt="" style={{ width: 16, height: 16, verticalAlign: "middle", marginRight: 3 }} />再生 残り{f.regen}</span> : null}
        {f.awaken ? <span style={{ ...theme.font.label, color: theme.text.danger, fontWeight: theme.weight.semibold }}><img src={IMG_ST_FIRE} alt="" style={{ width: 16, height: 16, verticalAlign: "middle", marginRight: 3 }} />野獣覚醒中</span> : null}
        <span style={{ ...stat, display: "inline-flex", alignItems: "center", gap: 3 }}>熱量 {Array.from({ length: HEAT_MAX }, (_: unknown, i: number) => <span key={i} style={{ display: "inline-block", width: 14, height: 10, borderRadius: 3, background: i < f.heat ? "linear-gradient(180deg, #fff3a0, #ff9a00 50%, #ff2a00)" : theme.fill.secondary, boxShadow: i < f.heat ? "0 0 8px #ff6a00" : "none", border: "1px solid rgba(255,200,80,0.55)" }} />)}</span>
        {f.chain > 0 ? <span style={{ ...theme.font.label, fontWeight: theme.weight.semibold }}>{f.chain}連鎖（{f.chainKind ? KIND_LABEL[f.chainKind] : ""}）</span> : null}
        {f.disc > 0 ? <span style={stat}>次カード気力-{f.disc}</span> : null}
        <span style={stat}>気力 {f.energy}</span>
        <span style={stat}>手札 {f.hand.length}</span>
        <span style={stat}><img src={IMG_CARD_BACK} alt="" style={{ width: 12, height: 16, verticalAlign: "middle", marginRight: 3, borderRadius: 2 }} />山札 {f.deck.length}</span>
      </div>
    </div>
  );
}

const KEYFRAMES = "@keyframes inmuShimmer{0%,100%{transform:translateY(0) skewX(0deg);filter:blur(0px)}50%{transform:translateY(-6px) skewX(1.5deg);filter:blur(1.5px)}}@keyframes inmuEmber{0%{transform:translateY(0) scale(1);opacity:0}10%{opacity:1}100%{transform:translateY(-110vh) translateX(var(--sx)) scale(.3);opacity:0}}@keyframes inmuNeon{0%,100%{text-shadow:0 0 4px #fff,0 0 12px #ff9a00,0 0 26px #ff3d00,3px 3px 0 #7a0000}50%{text-shadow:0 0 6px #fff,0 0 20px #ffd000,0 0 44px #ff3d00,3px 3px 0 #7a0000}}@keyframes inmuGlint{0%{transform:translateX(-120%)}100%{transform:translateX(420%)}}@keyframes inmuFlashBig{0%{opacity:.95;filter:brightness(2)}30%{opacity:.6}100%{opacity:0}}@keyframes inmuRays{0%{transform:translate(-50%,-50%) rotate(0deg) scale(.6);opacity:0}25%{opacity:.8}100%{transform:translate(-50%,-50%) rotate(60deg) scale(1.3);opacity:0}}@keyframes inmuFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}@keyframes inmuShake{0%{transform:translate(0,0)}15%{transform:translate(-6px,2px) rotate(-0.6deg)}30%{transform:translate(5px,-3px) rotate(0.5deg)}45%{transform:translate(-4px,3px)}60%{transform:translate(3px,-2px)}80%{transform:translate(-2px,1px)}100%{transform:translate(0,0)}}";

interface Pop { id: number; side: Side; text: string; crit: boolean; heal: boolean; x: number }
interface Particle { id: number; dx: number; dy: number; rot: number; ch: string; color: string; delay: number }
