const PARTICLE_CHARS: string[] = ["★", "114514", "✦", "810", "やったぜ", "●", "いいゾ〜", "✧", "364364", "！？", "🔥", "アツゥイ", "931", "💦"];
function burst(n: number, colors: string[], fallback: string): Particle[] {
  const out: Particle[] = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2 + Math.random() * 0.5;
    const r = 110 + Math.random() * 170;
    out.push({ id: i, dx: Math.round(Math.cos(a) * r), dy: Math.round(Math.sin(a) * r * 0.8 - 50), rot: Math.round(Math.random() * 720 - 360), ch: PARTICLE_CHARS[i % PARTICLE_CHARS.length] ?? "★", color: colors[i % colors.length] ?? fallback, delay: Math.round(Math.random() * 160) });
  }
  return out;
}
const SHAKE_SOFT = "0%{transform:translate(0,0)}20%{transform:translate(-4px,1px)}40%{transform:translate(4px,-2px)}60%{transform:translate(-3px,2px)}80%{transform:translate(2px,-1px)}100%{transform:translate(0,0)}";
