const HITSTOP = "0%,100%{transform:scale(1.03);filter:contrast(1.5) saturate(1.6) brightness(1.15)}";
const GLITCH = "0%{transform:scale(1);filter:none}10%{transform:scale(1.04) skewX(-2deg);filter:drop-shadow(4px 0 0 rgba(255,0,70,.75)) drop-shadow(-4px 0 0 rgba(0,230,255,.75)) contrast(1.4)}25%{transform:scale(1.02) translate(-6px,2px) skewX(3deg);filter:drop-shadow(-5px 0 0 rgba(255,0,70,.75)) drop-shadow(5px 0 0 rgba(0,230,255,.75)) hue-rotate(40deg)}45%{transform:scale(1.03) translate(5px,-3px);filter:drop-shadow(3px 0 0 rgba(255,0,70,.6)) drop-shadow(-3px 0 0 rgba(0,230,255,.6)) saturate(2) contrast(1.3)}65%{transform:scale(1.01) translate(-3px,1px) skewX(-1deg);filter:drop-shadow(2px 0 0 rgba(255,0,70,.5)) drop-shadow(-2px 0 0 rgba(0,230,255,.5))}100%{transform:scale(1);filter:none}";
const FX_KEYFRAMES = ["A", "B"].map((s: string) => `@keyframes inmuSh${s}{${SHAKE_SOFT}}@keyframes inmuHd${s}{${SHAKE_HARD}}@keyframes inmuSt${s}{${HITSTOP}}@keyframes inmuGl${s}{${GLITCH}}`).join("")
  + "@keyframes inmuFlash{0%{opacity:.7}100%{opacity:0}}"
  + "@keyframes inmuHaze{0%,100%{opacity:.55;transform:scale(1)}50%{opacity:.85;transform:scale(1.015)}}"
  + "@keyframes inmuSweat{0%{transform:translateY(-20px) scaleY(.8);opacity:0}10%{opacity:.85}85%{opacity:.7}100%{transform:translateY(105vh) scaleY(1.4);opacity:0}}"
  + "@keyframes inmuBlaze{0%,100%{opacity:.15}50%{opacity:.45}}"
  + "@keyframes inmuPop{0%{transform:translate(-50%,0) scale(.4);opacity:0}15%{transform:translate(-50%,-10px) scale(1.5);opacity:1}35%{transform:translate(-50%,-18px) scale(1)}100%{transform:translate(-50%,-56px) scale(1);opacity:0}}"
  + "@keyframes inmuBanner{0%{transform:translate(-50%,-50%) scale(2.6) rotate(-6deg);opacity:0}18%{transform:translate(-50%,-50%) scale(.92) rotate(-3deg);opacity:1}28%{transform:translate(-50%,-50%) scale(1.06) rotate(-3deg)}80%{transform:translate(-50%,-50%) scale(1) rotate(-3deg);opacity:1}100%{transform:translate(-50%,-50%) scale(1.2) rotate(-3deg);opacity:0}}"
  + "@keyframes inmuCut{0%{transform:translate(-50%,-50%) scale(1.8);opacity:0}20%{transform:translate(-50%,-50%) scale(.95);opacity:1}35%{transform:translate(-50%,-50%) scale(1.02)}85%{opacity:1}100%{transform:translate(-50%,-50%) scale(1);opacity:0}}"
  + "@keyframes inmuRing{0%{transform:translate(-50%,-50%) scale(.1);opacity:.9;border-width:10px}100%{transform:translate(-50%,-50%) scale(3.2);opacity:0;border-width:1px}}"
  + "@keyframes inmuAura{0%,100%{box-shadow:0 0 0 2px var(--aura),0 0 10px var(--aura)}50%{box-shadow:0 0 0 3px var(--aura),0 0 28px 6px var(--aura)}}"
  + "@keyframes inmuParticle{0%{transform:translate(0,0) scale(1.2) rotate(0deg);opacity:1}100%{transform:translate(var(--dx),var(--dy)) scale(.4) rotate(var(--rot));opacity:0}}"
  + "@keyframes inmuAwaken{0%{transform:translate(-50%,-50%) scale(.3) rotate(-12deg);opacity:0;filter:brightness(3)}20%{transform:translate(-50%,-50%) scale(1.08) rotate(2deg);opacity:1;filter:brightness(1.4)}80%{transform:translate(-50%,-50%) scale(1) rotate(0deg);opacity:1;filter:none}100%{transform:translate(-50%,-50%) scale(1.3);opacity:0}}"
  + "@keyframes inmuScan{0%{opacity:.6;background-position:0 0}100%{opacity:0;background-position:0 40px}}"
  + "@keyframes inmuStrip{0%{transform:translateX(-110%) skewX(-20deg);opacity:0}15%{transform:translateX(0) skewX(-12deg);opacity:1}80%{transform:translateX(0) skewX(-12deg);opacity:1}100%{transform:translateX(110%) skewX(-20deg);opacity:0}}"
  + "@keyframes inmuChip{0%{transform:scale(0) rotate(-40deg)}60%{transform:scale(1.5) rotate(10deg)}100%{transform:scale(1) rotate(0)}}"
  + "@keyframes inmuStatus{0%{transform:translateX(120%);opacity:0}12%{transform:translateX(-6%);opacity:1}20%{transform:translateX(0)}85%{opacity:1}100%{transform:translateX(30%);opacity:0}}"
  + "@keyframes inmuIcon{0%,100%{transform:scale(1)}50%{transform:scale(1.18) rotate(6deg)}}"
  + "@keyframes inmuChap{0%{opacity:0}12%{opacity:1}85%{opacity:1}100%{opacity:0}}"
  + "@keyframes inmuChapText{0%{transform:scale(2.4);letter-spacing:40px;filter:blur(6px)}25%{transform:scale(1);letter-spacing:6px;filter:none}100%{transform:scale(1.06)}}"
  + "@keyframes inmuZoom{0%{transform:scale(1.35);filter:contrast(1.8) saturate(2) blur(2px)}100%{transform:scale(1);filter:none}}";

export default function App() {
  const theme: any = { text: "#f8e8a0", bg: "#1a1511", accent: "#d4af37", border: "#665533", fill: "#2a2511", font: "16px", secondary: "#998866", elevated: "#3a3522", weight: "bold", dataviz: { red: "#cc4444", yellow: "#ccaa44", green: "#44cc44", blue: "#4488cc", purple: "#8844cc", primary: "#d4af37", base: "#665533" }, success: "#44cc44", primary: "#d4af37", base: "#665533", warning: "#ccaa44", danger: "#cc4444" };
  const [game, setGame] = useState<Game | null>(null);
  const [screen, setScreen] = useState<Screen>({ kind: "title" });
  const [sel, setSel] = useState<number | null>(null);
  const [muted, setMuted] = useState<boolean>(false);
  const seen = useRef<Seen>({ ...SEEN0 });
  const [fx, setFx] = useState<Fx>(FX0);
  const fxSeq = useRef<number>(0);
  const fxTimers = useRef<ReturnType<typeof setTimeout>[]>([]);
  useEffect(() => () => { fxTimers.current.forEach((t: ReturnType<typeof setTimeout>) => clearTimeout(t)); }, []);

  useEffect(() => {
    if (!game) return undefined;
    if (game.phase === "cpu") {
      const t = setTimeout(() => setGame((prev: Game | null) => (prev && prev.phase === "cpu" ? cpuAct(cloneG(prev)) : prev)), 850);
      return () => clearTimeout(t);
    }
    if (game.phase === "collapse") {
      const t = setTimeout(() => setGame((prev: Game | null) => (prev && prev.phase === "collapse" ? endRound(cloneG(prev)) : prev)), 1100);
      return () => clearTimeout(t);
    }
    return undefined;
  }, [game]);

  useEffect(() => {
    if (!game) { seen.current = { ...SEEN0 }; return undefined; }
    const s = seen.current;
    const timers: ReturnType<typeof setTimeout>[] = [];
    seen.current = { play: game.playSeq, col: game.collapses, res: game.result, init: true, php: game.p.hp, chp: game.c.hp, pheat: game.p.heat, cheat: game.c.heat, pch: game.p.chain, cch: game.c.chain, paw: game.p.awaken, caw: game.c.awaken, pst: game.p.stun, cst: game.c.stun, pvu: game.p.vuln, cvu: game.c.vuln, prg: game.p.regen, crg: game.c.regen, phand: game.p.hand.length, stg: game.stage };
    if (!s.init) return undefined;
    const cat = theme.dataviz.categorical;
    const red = theme.dataviz.negative;
    const hot = cat[1] ?? theme.dataviz.other;
    const cool = cat[0] ?? theme.dataviz.other;
    const kc = (k: Kind): string => (k === "atk" ? red : k === "def" ? cool : k === "heal" ? (cat[2] ?? theme.dataviz.other) : k === "meme" ? hot : theme.dataviz.other);
    const nk = (): number => { fxSeq.current += 1; return fxSeq.current; };
    const at = (ms: number, fn: () => void): void => {
      const t: ReturnType<typeof setTimeout> = setTimeout(() => { fxTimers.current = fxTimers.current.filter((x: ReturnType<typeof setTimeout>) => x !== t); fn(); }, ms);
      fxTimers.current.push(t);
    };
    const put = (ms: number, life: number, p: Partial<Fx>, clear: (f: Fx) => Partial<Fx> | null): void => {
      at(ms, () => {
        setFx((f: Fx) => ({ ...f, ...p }));
        at(life, () => setFx((f: Fx) => { const c = clear(f); return c ? { ...f, ...c } : f; }));
      });
    };
    const flash = (ms: number, color: string): void => { const k = nk(); put(ms, 400, { flash: { k, color } }, (f: Fx) => (f.flash && f.flash.k === k ? { flash: null } : null)); };
    const wrap = (ms: number, type: "soft" | "hard" | "glitch"): void => { const k = nk(); put(ms, type === "glitch" ? 950 : 650, { wrap: { k, type } }, (f: Fx) => (f.wrap && f.wrap.k === k ? { wrap: null } : null)); };
    const banner = (ms: number, text: string, color: string): void => { const k = nk(); put(ms, 1200, { banner: { k, text, color } }, (f: Fx) => (f.banner && f.banner.k === k ? { banner: null } : null)); };
    const party = (ms: number, n: number): void => { const k = nk(); const items = burst(n, [red, hot, cool, cat[2] ?? theme.dataviz.other], theme.text.primary); put(ms, 1750, { party: { k, items } }, (f: Fx) => (f.party && f.party.k === k ? { party: null } : null)); };
    let delay = 0;
    const played = game.playSeq > s.play && !!game.playKind;
    if (played && game.playKind) {
      const kind: Kind = game.playKind;
      sfx(kind);
      delay = 260;
      const re = /の【(.+)】$/;
      const line = [...game.log].reverse().find((l: LogLine) => re.test(l.text));
      const m = line ? re.exec(line.text) : null;
      const name = m && m[1] ? m[1] : KIND_LABEL[kind];
      const k = nk();
      put(0, 720, { cut: { k, text: `【${name}】`, color: kc(kind) } }, (f: Fx) => (f.cut && f.cut.k === k ? { cut: null } : null));
    }
    const hitAt = played ? 110 : 0;
    const dP = s.php - game.p.hp;
    const dC = s.chp - game.c.hp;
    ([["p", dP], ["c", dC]] as [Side, number][]).forEach(([side, d]: [Side, number]) => {
      if (d === 0) return;
      const pop: Pop = { id: nk(), side, text: d > 0 ? `-${d}` : `+${-d}`, crit: d >= 28, heal: d < 0, x: 25 + Math.round(Math.random() * 45) };
      at(hitAt, () => {
        setFx((f: Fx) => ({ ...f, pops: [...f.pops, pop].slice(-8) }));
        at(1050, () => setFx((f: Fx) => ({ ...f, pops: f.pops.filter((x: Pop) => x.id !== pop.id) })));
      });
    });
    const big = Math.max(dP, dC);
    let bText: string | null = null;
    let bColor = hot;
    if (big >= 18) {
      wrap(hitAt, "hard");
      const hv: SfxName = big >= 28 ? "crit" : Math.random() < 0.5 ? "impact" : "slam"; at(hitAt, () => sfx(hv));
      if (big >= 28) { flash(hitAt, red); bText = `${pick(CRIT_LINES)} ${big}ダメージ！`; bColor = red; }
    } else if (big >= 8) { wrap(hitAt, "soft"); at(hitAt, () => sfx("impact")); }
    const awP = game.p.awaken && !s.paw;
    const awC = game.c.awaken && !s.caw;
    if (awP || awC) {
      const k = nk();
      put(60, 1250, { awaken: k }, (f: Fx) => (f.awaken === k ? { awaken: null } : null));
      at(60, () => sfx("awaken"));
      flash(60, red);
      party(120, 22);
      if (!bText) { bText = awP ? "野獣覚醒！ 見とけよ見とけよ〜" : `${game.c.name}、覚醒（まずいですよ！）`; bColor = red; }
    }
    const heatP = game.p.heat >= HEAT_MAX && s.pheat < HEAT_MAX;
    const heatC = game.c.heat >= HEAT_MAX && s.cheat < HEAT_MAX;
    if ((heatP || heatC) && !bText) { bText = heatP ? "熱量MAX！ いいぞもっとやれ" : `${game.c.name}の熱量MAX（あっ、やばい）`; bColor = hot; flash(hitAt + 120, hot); at(hitAt + 120, () => sfx("hype")); }
    const chP = game.p.chain >= 2 && game.p.chain > s.pch;
    const chC = game.c.chain >= 2 && game.c.chain > s.cch;
    if ((chP || chC) && !bText) { const n = chP ? game.p.chain : game.c.chain; bText = `${n}連鎖！ ${pick(HYPE_LINES)}`; bColor = chP ? cool : hot; if (n >= 3) flash(hitAt + 120, bColor); at(hitAt + 120, () => sfx("hype")); }
    if (bText) banner(hitAt + 80, bText, bColor);
    const strip = (ms: number, n: number, color: string): void => { const k = nk(); put(ms, 1400, { combo: { k, n, color } }, (f: Fx) => (f.combo && f.combo.k === k ? { combo: null } : null)); };
    const status = (ms: number, text: string, color: string, icon: string): void => { const k = nk(); put(ms, 1500, { status: { k, text, color, icon } }, (f: Fx) => (f.status && f.status.k === k ? { status: null } : null)); };
    if (chP || chC) { const n = chP ? game.p.chain : game.c.chain; strip(hitAt, n, chP ? cool : hot); at(hitAt + 40, () => sfx("chain")); }
    if (heatP || heatC) at(hitAt + 40, () => sfx("heat"));
    const pName = "田所";
    const cName = game.c.name;
    const stS: Side | null = game.c.stun > s.cst ? "c" : game.p.stun > s.pst ? "p" : null;
    const vuS: Side | null = game.c.vuln > s.cvu ? "c" : game.p.vuln > s.pvu ? "p" : null;
    const rgS: Side | null = game.c.regen > s.crg ? "c" : game.p.regen > s.prg ? "p" : null;
    if (stS) { status(hitAt + 220, `${stS === "c" ? cName : pName} スタン！ 暴れんなよ…`, hot, IMG_ST_STUN); at(hitAt + 220, () => sfx("stun")); }
    else if (vuS) { status(hitAt + 220, `${vuS === "c" ? cName : pName} 脆弱化！ 被ダメ×1.5`, red, IMG_ST_VULN); at(hitAt + 220, () => sfx("debuff")); }
    else if (rgS) { status(hitAt + 220, `${rgS === "c" ? cName : pName} 再生開始（冷えてますよ〜）`, cool, IMG_ST_REGEN); at(hitAt + 220, () => sfx("regen")); }
    else if (awP || awC) status(hitAt + 260, awP ? "野獣覚醒：攻撃×2" : `${cName} 覚醒：攻撃×2`, red, IMG_ST_FIRE);
    if (game.p.hand.length > s.phand && !played) at(80, () => sfx("draw"));
    if (game.stage !== s.stg && s.stg >= 0) {
      const st = STAGES[game.stage];
      const k = nk();
      const chText = game.chapter === 2 ? "第二章　名状しがたき淫夢" : "第一章　下北沢、崩壊";
      put(0, 2000, { chapter: { k, text: st ? `STAGE ${st.code}` : chText, sub: st ? `${st.area} ／ ${chText}` : "" } }, (f: Fx) => (f.chapter && f.chapter.k === k ? { chapter: null } : null));
      at(0, () => sfx("chapter"));
    }
    const colName: SfxName = game.chapter === 2 ? "whisper" : game.collapses % 2 === 0 ? "collapse" : "quake";
    if (game.collapses > s.col) {
      timers.push(setTimeout(() => sfx(colName), delay));
      wrap(delay, "glitch");
      const k = nk();
      put(delay, 950, { scan: k }, (f: Fx) => (f.scan === k ? { scan: null } : null));
      delay += 700;
    }
    if (game.result && game.result !== s.res) {
      const r = game.result;
      timers.push(setTimeout(() => sfx(r === "win" ? "win" : "lose"), delay));
      if (r === "win") { party(delay, 30); banner(delay, "やりますねぇ！ 勝利！", hot); flash(delay, hot); }
      else if (r === "lose") { flash(delay, red); wrap(delay, "hard"); banner(delay, "ファッ！？ 敗北…", red); }
      else wrap(delay, "glitch");
    }
    return () => { timers.forEach((t: ReturnType<typeof setTimeout>) => clearTimeout(t)); };
  }, [game]);

  const toggleMute = useCallback((): void => {
    setMuted((m: boolean) => {
      const next = !m;
      sfxMuted = next;
      if (!next) { getCtx(); sfx("pass"); }
      return next;
    });
  }, []);

  useEffect(() => {
    if (screen.kind !== "battle" || !game || game.phase !== "player") return undefined;
    const handler = (e: Event): void => {
      if (!(e instanceof KeyboardEvent)) return;
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key;
      if (key >= "1" && key <= "9") {
        const idx = parseInt(key, 10) - 1;
        if (idx < game.p.hand.length) {
          const card = game.p.hand[idx];
          if (card) {
            e.preventDefault();
            setSel(card.uid);
            const cost = costOf(game, cardOf(card.key), "p");
            if (cost <= game.p.energy) {
              setTimeout(() => {
                setGame((prev: Game | null) => {
                  if (!prev || prev.phase !== "player") return prev;
                  const g = cloneG(prev);
                  playCard(g, "p", card.uid);
                  checkEnd(g);
                  return g;
                });
                setSel(null);
              }, 100);
            }
          }
        }
      } else if (key === "Enter" || key === " ") {
        e.preventDefault();
        getCtx();
        sfx("pass");
        setSel(null);
        setGame((prev: Game | null) => {
          if (!prev || prev.phase !== "player") return prev;
          const g = cloneG(prev);
          endTurn(g, "p");
          if (!checkEnd(g)) g.phase = "cpu";
          return g;
        });
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [screen, game, sel]);

  const startStage = useCallback((si: number): void => {
    getCtx();
    sfx("start");
    seen.current = { ...SEEN0 };
    setFx(FX0);
    setSel(null);
    setGame(newGame(si));
    setScreen({ kind: "battle" });
  }, []);
  const toTitle = useCallback((): void => { setSel(null); setGame(null); setScreen({ kind: "title" }); }, []);
  const openStory = useCallback((scenes: Scene[], next: number | null): void => {
    getCtx();
    sfx("pass");
    setSel(null);
    setGame(null);
    setScreen({ kind: "story", scenes, idx: 0, next });
  }, []);
  const retry = useCallback((): void => { if (game) startStage(game.stage); }, [game, startStage]);
  const goNext = useCallback((): void => {
    if (!game) return;
    const a = scenesAfter(game.stage);
    openStory(a.scenes, a.next);
  }, [game, openStory]);
  const advance = useCallback((): void => {
    if (screen.kind !== "story") return;
    if (screen.idx < screen.scenes.length - 1) { sfx("pass"); setScreen({ kind: "story", scenes: screen.scenes, idx: screen.idx + 1, next: screen.next }); return; }
    if (screen.next !== null) startStage(screen.next); else toTitle();
  }, [screen, startStage, toTitle]);
  const skipStory = useCallback((): void => {
    if (screen.kind !== "story") return;
    setScreen({ kind: "story", scenes: screen.scenes, idx: screen.scenes.length - 1, next: screen.next });
  }, [screen]);

  const playSelected = useCallback((): void => {
    if (sel === null) return;
    const uid = sel;
    getCtx();
    setSel(null);
    setGame((prev: Game | null) => {
      if (!prev || prev.phase !== "player") return prev;
      const g = cloneG(prev);
      const inst = g.p.hand.find((i: Inst) => i.uid === uid);
      if (!inst || costOf(g, cardOf(inst.key), "p") > g.p.energy) return prev;
      playCard(g, "p", uid);
      checkEnd(g);
      return g;
    });
  }, [sel]);

  const pass = useCallback((): void => {
    getCtx();
    sfx("pass");
    setSel(null);
    setGame((prev: Game | null) => {
      if (!prev || prev.phase !== "player") return prev;
      const g = cloneG(prev);
      endTurn(g, "p");
      g.phase = "cpu";
      return g;
    });
  }, []);

  const heatAct = useCallback((kind: "kiai" | "awaken"): void => {
    getCtx();
    sfx("meme");
    setGame((prev: Game | null) => {
      if (!prev || prev.phase !== "player") return prev;
      const g = cloneG(prev);
      return useHeat(g, "p", kind) ? g : prev;
    });
  }, []);

  const cat = theme.dataviz.categorical;
  const eld = !!game && game.chapter === 2;
  const colorP = (eld ? cat[2] : cat[0]) ?? theme.dataviz.other;
  const colorC = cat[1] ?? theme.dataviz.other;
  const kindColor = (k: Kind): string =>
    k === "atk" ? theme.dataviz.negative : k === "def" ? colorP : k === "heal" ? (cat[2] ?? theme.dataviz.other) : k === "meme" ? colorC : theme.dataviz.other;

  const root: CSSProperties = { fontFamily: theme.font.family, color: theme.text.primary, background: theme.bg.base, backgroundImage: `radial-gradient(ellipse at 50% -10%, ${eld ? "rgba(120,40,220,0.30)" : "rgba(255,110,0,0.28)"}, transparent 60%), radial-gradient(ellipse at 50% 115%, ${eld ? "rgba(60,0,120,0.30)" : "rgba(255,40,0,0.20)"}, transparent 55%)`, padding: 16, display: "flex", flexDirection: "column", gap: 16, boxSizing: "border-box", width: "100%" };
  const panel: CSSProperties = { border: `1px solid ${theme.border.default}`, borderRadius: 12, padding: 14, background: theme.bg.elevated, boxShadow: "0 6px 18px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.07)" };
  const panelTitle: CSSProperties = { ...theme.font.body2, fontWeight: theme.weight.semibold, marginBottom: 8 };
  const sub: CSSProperties = { ...theme.font.body2, color: theme.text.secondary };
  const tint = eld ? "rgba(120,40,220," : "rgba(255,110,0,";
  const neon: CSSProperties = { fontWeight: 900, color: "#fff7d6", letterSpacing: 1, animation: "inmuNeon 1.6s ease-in-out infinite" };
  const muteBtn = <button onClick={toggleMute} style={{padding:"8px 16px",background:"#666",color:"#fff",border:"none",borderRadius:"4px",cursor:"pointer"}}>{muted ? "音：OFF" : "音：ON"}</button>;

  if (screen.kind === "story") {
    const sc = screen.scenes[screen.idx] ?? screen.scenes[0];
    if (sc) {
      const last = screen.idx >= screen.scenes.length - 1;
      const imgSrc = sc.pic ? sc.pic : sc.img === "title" ? IMG_TITLE : sc.img === "hero" ? IMG_HERO : IMG_COLLAPSE;
      return (
        <div style={root}>
          <style>{KEYFRAMES}</style>
          <div key={screen.idx} style={{ ...panel, padding: 24, display: "flex", flexDirection: "column", gap: 14, animation: sc.eldritch ? "inmuShake 0.6s ease-out" : undefined }}>
            <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
              <span style={{ ...theme.font.label, color: theme.text.tertiary }}>{sc.tag}（{screen.idx + 1} / {screen.scenes.length}）</span>
              {muteBtn}
            </div>
            <img src={imgSrc} alt={sc.title} style={{ width: "100%", maxWidth: sc.pic ? 220 : 520, aspectRatio: sc.pic ? "1 / 1" : sc.img === "collapse" ? "16 / 7" : "4 / 3", objectFit: "cover", borderRadius: 12, alignSelf: "center", border: "3px solid #e0a800", boxShadow: "0 0 24px rgba(255,170,40,0.55)", filter: sc.eldritch ? ELDRITCH_FILTER : "none" }} />
            <div style={{ ...theme.font.heading2, ...neon, fontSize: "clamp(22px, 5vw, 36px)" }}>{sc.title}</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {sc.lines.map((l: string, i: number) => (
                <div key={i} style={{ ...theme.font.body1, color: l.startsWith("「") ? theme.text.primary : theme.text.secondary }}>{l}</div>
              ))}
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              <button onClick={advance} style={{padding:"10px 20px",background:"#d4af37",color:"#1a1511",border:"none",borderRadius:"4px",fontSize:"18px",fontWeight:"bold",cursor:"pointer"}}>{last ? (screen.next !== null ? "バトル開始" : "タイトルへ") : "次へ"}</button>
              {!last ? <button onClick={skipStory} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"16px",fontWeight:"bold",cursor:"pointer"}}>スキップ</button> : null}
              {!last || screen.next !== null ? <button onClick={toTitle} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"16px",fontWeight:"bold",cursor:"pointer"}}>タイトルへ</button> : null}
            </div>
          </div>
        </div>
      );
    }
  }

  if (screen.kind === "select") {
    return (
      <div style={root}>
        <div style={{ ...panel, padding: 24, display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
            <div style={{ ...theme.font.heading2, fontWeight: theme.weight.semibold }}>章選択</div>
            {muteBtn}
          </div>
          {([1, 2] as (1 | 2)[]).map((ch: 1 | 2) => (
            <div key={ch} style={{ display: "flex", flexDirection: "column", gap: 8, borderTop: `1px solid ${theme.border.default}`, paddingTop: 14 }}>
              <div style={{ ...theme.font.heading3, fontWeight: theme.weight.semibold }}>{CHAPTER_TITLE[ch]}</div>
              <div style={sub}>{CHAPTER_BLURB[ch]}</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                <button onClick={() => openStory(scenesBefore(firstOf(ch), false), firstOf(ch))} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"18px",fontWeight:"bold",cursor:"pointer"}}>章のはじめから</button>
                {STAGES.map((s: Stage, i: number) => (s.chapter === ch ? (
                  <span key={s.code}><button onClick={() => openStory(scenesBefore(i, true), i)} style={{padding:"8px",background:"#666",color:"#fff",border:"none",borderRadius:"4px",cursor:"pointer"}}>{`${s.code} ${s.enemy}`}</button></span>
                ) : null))}
              </div>
            </div>
          ))}
          <div><button onClick={toTitle} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"16px",fontWeight:"bold",cursor:"pointer"}}>タイトルへ</button></div>
        </div>
      </div>
    );
  }

  if (!game || screen.kind !== "battle") {
    const rules: string[] = [
      "対CPUのターン制カードバトル。HP114を先に0にした方の勝ち",
      "毎ラウンド、気力3の続く限り何枚でも出せる。1枚も出さずに終えるとパス（1枚ドロー＋HP3）",
      "同タイプ連打で連鎖。2連鎖からボーナス＋熱量+1、3連鎖以上で次カード気力-1。「あっ、そうだ」は連鎖をつなぐ",
      "熱量（最大5）：気力を余らせても溜まる。3で気力+1、5で野獣覚醒（次の攻撃×2・貫通）、または眼光カードに全ぶっぱ",
      "状態：脆弱（被ダメ×1.5）、スタン（次R気力-2、シールド10以上で無効）、再生（毎R HP+4、回復反転中は逆効果）",
      "崩壊ダメージはシールドが半分肩代わり。次の崩壊は予報が出る（天気予報カードで引き直し）",
      "CPUも同じルールで連鎖・熱量・状態を使ってくる。当たり前だよなぁ？",
      "ラウンド終了ごとに世界が崩壊。地形・ルール・手札・マップがランダムに壊れる",
      "マップの全区画がすべて崩落すると終焉モード（全ダメージ×1.5）",
      "崩壊ダメージではHP1が必ず残る。とどめはカードで刺せ",
      "物語モード：第1章（5戦）→第2章（4戦）。勝てば物語が進み、負けたらその戦いを再戦",
      "第2章ではSAN（正気度）が登場。汚染のたびに減り、50未満で手札上限4、25未満で3、0で発狂",
      "ボス戦は偶数ラウンドの終わりに崩壊が1回増える",
      "戦術：敵の意図（攻撃予告）が見える。大技には受け流し、覚醒には「お前のものが欲しいとか？」",
      "戦術：筋トレは今の気力を次ラウンドに貯金。熱量は気合・覚醒・眼光・ヤッタネ（回復）の4択",
    ];
    return (
      <div style={root}>
        <style>{KEYFRAMES}</style>
        <div style={{ ...panel, padding: 24, display: "flex", flexDirection: "column", gap: 14 }}>
          <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
            <div style={{ ...theme.font.label, color: theme.text.tertiary }}>{CHAPTER_TITLE[1]}／{CHAPTER_TITLE[2]}</div>
            {muteBtn}
          </div>
          <img src={IMG_TITLE} alt="崩壊淫夢カードバトル タイトルイラスト" style={{ width: "100%", maxWidth: 420, aspectRatio: "1 / 1", objectFit: "cover", borderRadius: 12, alignSelf: "center", border: "3px solid #e0a800", boxShadow: "0 0 0 2px #5a3a00, 0 0 36px rgba(255,140,0,0.6)" }} />
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8, justifyContent: "center" }}>
            {CAST.map((c: CastEntry) => (
              <div key={c.name} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 2, width: 84 }}>
                <img src={c.img} alt={c.name} style={{ width: 72, height: 72, borderRadius: 12, objectFit: "cover", border: "2px solid #e0a800", boxShadow: "0 0 12px rgba(255,170,40,0.6)", animation: "inmuFloat 3s ease-in-out infinite" }} />
                <span style={{ ...theme.font.label, color: theme.text.secondary, textAlign: "center" }}>{c.name}</span>
                <span style={{ ...theme.font.label, color: theme.text.tertiary }}>{c.role}</span>
              </div>
            ))}
          </div>
          <div style={{ ...theme.font.heading1, ...neon, fontSize: "clamp(30px, 7vw, 54px)", lineHeight: 1.1, textAlign: "center" }}>崩壊淫夢カードバトル<div style={{ fontSize: "0.5em", marginTop: 4 }}>〜灼熱の夏の暑い日〜</div></div>
          <div style={{ ...theme.font.label, color: theme.text.secondary, textAlign: "center", marginTop: 8 }}>操作: 1-9 / Enter / M / Esc</div>
          <div style={{ ...theme.font.heading3, fontWeight: theme.weight.semibold, color: theme.text.danger }}>王道を征く！ こ↑こ↓から始まる、114514℃の語録決戦（迫真）</div>
          <div style={sub}>ムシムシの下北沢、汗だくの灼熱屋上、麦茶はもうぬるい。俺、田所浩二（24歳、学生）。毎ターン崩れていく下北沢を抜け、古き神々に汚染されたミームの島々を、語録のカードで殴り渡る。いいよ！こいよ！ そんな装備で大丈夫か？「大丈夫だ、問題ない（大嘘）」 下北沢、まずうちさぁ屋上、迫真空手部、アイスティーの屋上、王道を征くソープ系迷宮、そして無限の先輩の家——聖地を巡り、TDN・野獣大先輩を倒せ。乱入するDB・KBTITにも注意。オッスお願いしまーす！</div>
          <ul style={{ margin: 0, paddingLeft: 20, display: "flex", flexDirection: "column", gap: 4 }}>
            {rules.map((r: string) => <li key={r} style={theme.font.body2}>{r}</li>)}
          </ul>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
            {(Object.keys(KIND_LABEL) as Kind[]).map((k: Kind) => (
              <span key={k} style={{ ...theme.font.label, display: "inline-flex", alignItems: "center", gap: 6, border: `1px solid ${theme.border.default}`, borderRadius: 9999, padding: "3px 10px 3px 4px" }}>
                <KindIcon kind={k} size={22} />
                <span style={{ width: 8, height: 8, borderRadius: 9999, background: kindColor(k) }} />
                {KIND_LABEL[k]}
              </span>
            ))}
          </div>
          <div style={{ ...theme.font.label, color: theme.text.tertiary }}>カード{ALL_CARDS.length}種／崩壊イベント{EVENTS.length}種＋神性汚染イベント{EVENTS2.length}種／全{STAGES.length}戦／効果音はすべてブラウザ内で合成</div>
          <div style={{ ...theme.font.label, color: theme.text.tertiary }}>{IMG_CREDIT}</div>
          <div style={{ ...theme.font.label, color: theme.text.tertiary }}>{IMG_CREDIT2}</div>
          <div style={{ ...theme.font.label, color: theme.text.tertiary }}>{IMG_CREDIT3}</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
            <button onClick={() => openStory(scenesBefore(0, false), 0)} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"18px",fontWeight:"bold",cursor:"pointer"}}>物語をはじめる</button>
            <button onClick={() => setScreen({ kind: "select" })} style={{padding:"8px 16px",background:"#666",color:"#fff",border:"none",borderRadius:"4px",cursor:"pointer"}}>章選択</button>
          </div>
        </div>
      </div>
    );
  }

  const g = game;
  const stg = (STAGES[g.stage] ?? STAGES[0]) as Stage;
  const aliveTiles = g.tiles.filter((t: Tile) => t.alive).length;
  const selInst = sel !== null ? g.p.hand.find((i: Inst) => i.uid === sel) : undefined;
  const selDef = selInst ? cardOf(selInst.key) : undefined;
  const selPlayable = !!selDef && g.phase === "player" && costOf(g, selDef, "p") <= g.p.energy;
  const status =
    g.phase === "player" ? "あなたのターン：気力の続く限り何枚でも。同タイプ連打で連鎖（見とけよ見とけよ〜）" :
    g.phase === "cpu" ? `${g.c.name}が考え中…（${THINK_LINES[g.round % THINK_LINES.length] ?? "あくしろよ"}）` :
    g.phase === "collapse" ? "ラウンド終了。世界が崩壊していく…（迫真）" :
    g.result === "win" ? "勝利！ やりますねぇ！ いいゾ〜これ" : g.result === "lose" ? "敗北… ファッ！？（迫真）" : "引き分け（世界ごと消滅、これもうわかんねぇな）";

  const pickCard = (uid: number): void => { if (g.phase === "player") setSel(uid === sel ? null : uid); };
  const onCardKey = (e: KeyboardEvent<HTMLDivElement>, uid: number): void => {
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pickCard(uid); }
  };
  const whoColor = (w: Who): string => (w === "p" ? colorP : w === "c" ? colorC : theme.border.strong);
  const ws = fx.wrap ? (fx.wrap.k % 2 === 0 ? "A" : "B") : "";
  const wrapAnim = !fx.wrap ? undefined : fx.wrap.type === "soft" ? `inmuSh${ws} 0.35s ease-out` : fx.wrap.type === "hard" ? `inmuSt${ws} 0.11s steps(1), inmuHd${ws} 0.5s ease-out 0.11s` : `inmuGl${ws} 0.9s steps(8, end)`;
  const auraOf = (f: Fighter, c: string): string | undefined => (f.awaken || f.heat >= HEAT_MAX ? theme.dataviz.negative : f.chain >= 3 ? c : undefined);

  return (
    <div style={{ ...root, position: "relative", overflow: "hidden", animation: wrapAnim }}>
      <style>{KEYFRAMES + FX_KEYFRAMES}</style>
      <div aria-hidden="true" style={{ position: "absolute", inset: 0, zIndex: 25, pointerEvents: "none", background: "radial-gradient(ellipse at 50% 0%, rgba(255,120,0,0.22), rgba(255,40,0,0.10) 55%, rgba(255,90,0,0.16))", mixBlendMode: "multiply", animation: "inmuHaze 3.6s ease-in-out infinite" }} />
      {[6, 17, 29, 41, 53, 64, 76, 88, 95].map((x: number, i: number) => <div key={`sw${x}`} aria-hidden="true" style={{ position: "absolute", top: 0, left: `${x}%`, width: 7, height: 11, zIndex: 26, pointerEvents: "none", borderRadius: "50% 50% 50% 50% / 65% 65% 35% 35%", background: "linear-gradient(180deg, rgba(200,235,255,0.95), rgba(120,190,255,0.55))", boxShadow: "0 0 4px rgba(150,210,255,0.8)", animation: `inmuSweat ${3.2 + (i % 4) * 0.9}s linear ${i * 0.7}s infinite` }} />)}
      <div aria-hidden="true" style={{ position: "absolute", inset: 0, zIndex: 24, pointerEvents: "none", background: `radial-gradient(ellipse at center, transparent 55%, ${eld ? "rgba(30,0,60,0.55)" : "rgba(70,10,0,0.5)"} 100%)` }} />
      <div aria-hidden="true" style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: "40%", zIndex: 24, pointerEvents: "none", background: `linear-gradient(0deg, ${tint}0.20), transparent)`, animation: "inmuShimmer 2.4s ease-in-out infinite" }} />
      {[8, 19, 31, 44, 57, 69, 81, 92].map((x: number, i: number) => <span key={`em${x}`} aria-hidden="true" style={{ position: "absolute", bottom: -10, left: `${x}%`, width: 4 + (i % 3) * 2, height: 4 + (i % 3) * 2, borderRadius: 9999, zIndex: 26, pointerEvents: "none", background: eld ? "#c58bff" : "#ffb347", boxShadow: `0 0 8px ${eld ? "#a050ff" : "#ff6a00"}`, animation: `inmuEmber ${5 + (i % 4)}s linear ${i * 0.6}s infinite`, "--sx": `${(i % 2 ? 1 : -1) * (10 + i * 3)}px` } as unknown as CSSProperties} />)}
      {g.p.heat >= HEAT_MAX || g.c.heat >= HEAT_MAX || g.p.awaken || g.c.awaken ? <div aria-hidden="true" style={{ position: "absolute", inset: 0, zIndex: 27, pointerEvents: "none", background: "radial-gradient(circle at 50% 60%, rgba(255,220,0,0.35), rgba(255,60,0,0.55) 60%, rgba(180,0,0,0.6))", mixBlendMode: "screen", animation: "inmuBlaze 0.7s ease-in-out infinite" }} /> : null}
      {g.p.heat >= HEAT_MAX || g.c.heat >= HEAT_MAX ? <div aria-hidden="true" style={{ position: "absolute", top: 8, left: "50%", transform: "translateX(-50%)", zIndex: 31, pointerEvents: "none", ...neon, fontSize: "clamp(22px, 5vw, 34px)", whiteSpace: "nowrap" }}>熱量MAX！ 夏の暑い日（迫真）</div> : null}
      {fx.flash ? <div key={fx.flash.k} aria-hidden="true" style={{ position: "absolute", inset: 0, zIndex: 30, pointerEvents: "none", background: fx.flash.color, mixBlendMode: "screen", animation: "inmuFlashBig 0.4s ease-out forwards" }} /> : null}
      {fx.flash ? <div key={`r${fx.flash.k}`} aria-hidden="true" style={{ position: "absolute", left: "50%", top: "45%", width: "160%", aspectRatio: "1 / 1", zIndex: 30, pointerEvents: "none", background: `repeating-conic-gradient(${fx.flash.color} 0deg 6deg, transparent 6deg 18deg)`, mixBlendMode: "screen", animation: "inmuRays 0.4s ease-out forwards" }} /> : null}
      {fx.scan ? <div key={fx.scan} aria-hidden="true" style={{ position: "absolute", inset: 0, zIndex: 29, pointerEvents: "none", backgroundImage: "repeating-linear-gradient(0deg, rgba(255,255,255,0.10) 0px, rgba(255,255,255,0.10) 2px, rgba(0,0,0,0.22) 2px, rgba(0,0,0,0.22) 4px)", animation: "inmuScan 0.95s steps(6, end) forwards" }} /> : null}
      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-between", alignItems: "center", gap: 8, position: "relative", isolation: "isolate", overflow: "hidden", borderRadius: 12, padding: "12px 14px", border: "2px solid #e0a800", boxShadow: `0 0 0 1px #5a3a00, 0 0 22px ${tint}0.45)` }}>
        <div aria-hidden="true" style={{ position: "absolute", inset: 0, zIndex: -1, backgroundImage: `url(${STAGE_BG[stg.code] ?? ENEMY_IMG[stg.code] ?? IMG_TITLE})`, backgroundSize: "cover", backgroundPosition: "center", opacity: 0.5, filter: g.chapter === 2 ? `${ELDRITCH_FILTER} blur(1px)` : "blur(1px)" }} />
        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
          <div style={{ ...theme.font.label, color: theme.text.tertiary }}>{CHAPTER_TITLE[g.chapter]}</div>
          <div style={{ ...theme.font.heading2, ...neon, fontSize: "clamp(20px, 4.4vw, 30px)" }}>{stg.code}「{stg.area}」{stg.boss ? "（ボス戦）" : ""}</div>
          {g.chapter === 2 ? (
            <div style={{ ...theme.font.body2, fontWeight: theme.weight.semibold, color: g.san < 25 ? theme.text.danger : g.san < 50 ? theme.text.warning : theme.text.secondary }}>SAN {g.san} / 100（手札上限 {handLimit(g, "p")}）</div>
          ) : null}
          {g.chapter === 2 ? <div style={{ width: 200, maxWidth: "100%" }}><HpBar value={g.san} max={100} color={g.san < 25 ? theme.dataviz.negative : "#9b5cff"} /></div> : null}
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "4px 16px", alignItems: "center" }}>
          <span style={sub}>第{g.round}ラウンド</span>
          <span style={sub}>残り区画 {aliveTiles}/{g.tiles.length}</span>
          <span style={sub}>崩壊回数 {g.collapses}</span>
          {g.endless ? <span style={{ ...theme.font.body2, color: theme.text.danger, fontWeight: theme.weight.semibold }}>終焉モード：全ダメージ×1.5</span> : null}
          {muteBtn}
        </div>
      </div>

      <div style={{ ...theme.font.body1, fontWeight: theme.weight.medium }}>{status}</div>
      {g.phase !== "end" ? (
        <div style={{ ...panel, display: "flex", flexDirection: "column", gap: 4, padding: 10 }}>
          <div style={{ ...theme.font.body2, fontWeight: theme.weight.semibold }}>{g.c.name}の意図：{intentOf(g)}</div>
          <div style={{ ...theme.font.label, color: theme.text.secondary }}>{STAGE_TIPS[stg.code] ?? ""}{g.p.parry > 0 ? "／受け流し構え中" : ""}{g.p.bank > 0 ? `／筋肉貯金 気力+${g.p.bank}` : ""}</div>
        </div>
      ) : null}

      {g.phase === "end" ? (
        <div style={{ ...panel, border: `3px solid ${g.result === "win" ? "#ffd84a" : "#b00020"}`, boxShadow: `0 0 32px ${g.result === "win" ? "rgba(255,200,60,0.7)" : "rgba(200,0,30,0.6)"}`, backgroundImage: `radial-gradient(ellipse at 30% 50%, ${g.result === "win" ? "rgba(255,190,40,0.35)" : "rgba(150,0,20,0.4)"}, transparent 70%)`, display: "flex", flexWrap: "wrap", gap: 14, alignItems: "center" }}>
          <img src={g.result === "win" ? IMG_HERO : IMG_COLLAPSE} alt={g.result === "win" ? "勝利した田所浩二" : "崩壊した世界"} style={{ width: g.result === "win" ? 96 : 170, height: 96, objectFit: "cover", borderRadius: 10, border: `1px solid ${theme.border.default}`, flex: "0 0 auto" }} />
          {g.result === "win" ? <img src={IMG_DOYA} alt="ドヤ顔先輩" style={{ width: 120, height: 120, objectFit: "cover", borderRadius: 14, border: "3px solid #ffd84a", boxShadow: "0 0 24px rgba(255,200,60,0.8)", animation: "inmuFloat 2s ease-in-out infinite", flex: "0 0 auto" }} /> : <img src={IMG_KOKO} alt="聖地こ↑こ↓" style={{ width: 96, height: 72, objectFit: "cover", borderRadius: 10, border: `1px solid ${theme.border.default}`, flex: "0 0 auto", filter: "grayscale(0.8)" }} />}
          <div style={{ display: "flex", flexDirection: "column", gap: 10, flex: "1 1 220px" }}>
            <div style={{ ...theme.font.heading1, fontSize: "clamp(34px, 7vw, 56px)", fontWeight: 900, fontStyle: "italic", textShadow: `0 0 12px ${g.result === "win" ? "#ffb000" : "#ff0030"}, 3px 3px 0 #000`, color: g.result === "win" ? theme.text.success : g.result === "lose" ? theme.text.danger : theme.text.primary }}>
              {g.result === "win" ? "勝利" : g.result === "lose" ? "敗北" : "引き分け"}
            </div>
            <div style={sub}>
              {g.result === "win" ? `${g.c.name}を撃破。崩壊${g.collapses}回の淫夢を生き延びた。いいゾ〜これ` : g.result === "lose" ? `${g.round}ラウンド目、田所浩二は崩れゆく淫夢に沈んだ。ダメみたいですね（諦観）` : "あーもう滅茶苦茶だよ"}
              {g.result === "win" ? `　${RESULT_WIN[g.collapses % RESULT_WIN.length] ?? ""}` : g.result === "lose" ? `　${RESULT_LOSE[g.round % RESULT_LOSE.length] ?? ""}` : ""}
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {g.result === "win" ? (
                <button onClick={goNext} style={{padding:"10px 20px",background:"#d4af37",color:"#1a1511",border:"none",borderRadius:"4px",fontSize:"18px",fontWeight:"bold",cursor:"pointer"}}>{STAGES[g.stage + 1] ? "物語を進める" : "エンディングへ"}</button>
              ) : (
                <button onClick={retry} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"18px",fontWeight:"bold",cursor:"pointer"}}>再戦する</button>
              )}
              <button onClick={toTitle} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"16px",fontWeight:"bold",cursor:"pointer"}}>タイトルへ</button>
            </div>
          </div>
        </div>
      ) : null}

      <div style={{ position: "relative" }}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 12 }}>
          <FighterPanel f={g.p} color={colorP} isPlayer={true} active={g.phase === "player"} pops={fx.pops.filter((p: Pop) => p.side === "p")} aura={auraOf(g.p, colorP)} />
          <FighterPanel f={g.c} color={colorC} isPlayer={false} active={g.phase === "cpu"} portrait={ENEMY_IMG[stg.code]} eerie={g.chapter === 2} pops={fx.pops.filter((p: Pop) => p.side === "c")} aura={auraOf(g.c, colorC)} />
        </div>
        <div aria-hidden="true" style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 4 }}>
          {fx.cut ? (
            <div key={fx.cut.k} style={{ position: "absolute", inset: 0 }}>
              <span style={{ position: "absolute", left: "50%", top: "32%", width: 120, height: 120, borderRadius: 9999, border: `8px solid ${fx.cut.color}`, animation: "inmuRing 0.6s ease-out forwards" }} />
              <span style={{ position: "absolute", left: "50%", top: "32%", width: 120, height: 120, borderRadius: 9999, border: `5px solid ${fx.cut.color}`, animation: "inmuRing 0.7s ease-out 0.1s both" }} />
              <div style={{ position: "absolute", left: "50%", top: "32%", maxWidth: "88%", padding: "10px 20px", borderRadius: 12, border: `3px solid ${fx.cut.color}`, background: theme.bg.elevated, boxShadow: `0 0 0 4px ${theme.bg.base}, 0 0 28px ${fx.cut.color}`, ...theme.font.heading2, fontWeight: theme.weight.semibold, color: theme.text.primary, textAlign: "center", animation: "inmuCut 0.72s ease-out forwards" }}>{fx.cut.text}</div>
            </div>
          ) : null}
          {fx.awaken !== null ? (
            <img key={fx.awaken} src={IMG_G_AWAKEN} alt="" style={{ position: "absolute", left: "50%", top: "50%", width: 150, height: 150, objectFit: "cover", borderRadius: 16, border: `3px solid ${theme.dataviz.negative}`, boxShadow: `0 0 36px ${theme.dataviz.negative}`, animation: "inmuAwaken 1.25s ease-out forwards" }} />
          ) : null}
          {fx.banner ? (
            <div key={fx.banner.k} style={{ position: "absolute", left: "50%", top: "66%", width: "94%", textAlign: "center", ...theme.font.heading1, fontSize: "clamp(32px, 8vw, 68px)", lineHeight: 1.1, fontWeight: 900, fontStyle: "italic", color: "#fffbe8", textShadow: `0 0 4px #fff, 0 0 14px ${fx.banner.color}, 0 0 36px ${fx.banner.color}, 4px 4px 0 #000, -2px -2px 0 ${fx.banner.color}`, animation: "inmuBanner 1.2s cubic-bezier(.2,.8,.3,1) forwards", zIndex: 2 }}>{fx.banner.text}</div>
          ) : null}
          {fx.combo ? (
            <div key={fx.combo.k} style={{ position: "absolute", left: 0, right: 0, top: "16%", padding: "12px 0", display: "flex", alignItems: "center", justifyContent: "center", gap: 6, background: `linear-gradient(90deg, transparent, ${fx.combo.color} 30%, ${fx.combo.color} 70%, transparent)`, animation: "inmuStrip 1.4s cubic-bezier(.2,.8,.3,1) forwards", zIndex: 2, pointerEvents: "none" }}>
              {Array.from({ length: Math.min(fx.combo.n, 8) }, (_: unknown, i: number) => (
                <span key={i} style={{ ...theme.font.heading3, animation: `inmuChip .45s ${i * 70}ms both` }}>🔥</span>
              ))}
              <span style={{ ...theme.font.heading2, letterSpacing: 3, fontSize: "clamp(24px, 5vw, 42px)", fontWeight: 900, fontStyle: "italic", color: "#fffbe8", textShadow: `0 0 10px #fff, 0 0 24px ${fx.combo.color}, 3px 3px 0 #000` }}>{fx.combo.n} COMBO!!</span>
            </div>
          ) : null}
          {fx.status ? (
            <div key={fx.status.k} style={{ position: "absolute", right: "4%", top: "30%", display: "flex", alignItems: "center", gap: 8, padding: "6px 12px 6px 6px", borderRadius: 999, background: theme.bg.elevated, border: `2px solid ${fx.status.color}`, boxShadow: `0 0 18px ${fx.status.color}`, animation: "inmuStatus 1.5s ease-out forwards", zIndex: 2, pointerEvents: "none" }}>
              <img src={fx.status.icon} alt="" style={{ width: 36, height: 36, borderRadius: 999, animation: "inmuIcon .6s ease-in-out infinite" }} />
              <span style={{ ...theme.font.body2, fontWeight: theme.weight.semibold, color: theme.text.primary }}>{fx.status.text}</span>
            </div>
          ) : null}
          {fx.chapter ? (
            <div key={fx.chapter.k} style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, background: `linear-gradient(180deg, transparent 25%, rgba(0,0,0,.82) 38%, rgba(0,0,0,.82) 62%, transparent 75%)`, animation: "inmuChap 2s ease-in-out forwards", zIndex: 3, pointerEvents: "none" }}>
              <div style={{ ...theme.font.heading1, fontSize: "clamp(30px, 7vw, 56px)", fontWeight: theme.weight.semibold, color: "#fff", letterSpacing: 6, textShadow: `0 0 16px ${theme.dataviz.negative}, 3px 3px 0 ${theme.dataviz.negative}`, animation: "inmuChapText 2s ease-out forwards" }}>{fx.chapter.text}</div>
              {fx.chapter.sub ? <div style={{ ...theme.font.body2, color: "#fff", opacity: 0.9 }}>{fx.chapter.sub}</div> : null}
            </div>
          ) : null}
          {fx.party ? (
            <div key={fx.party.k} style={{ position: "absolute", left: "50%", top: "45%", width: 0, height: 0 }}>
              {fx.party.items.map((p: Particle) => (
                <span key={p.id} style={{ position: "absolute", left: 0, top: 0, ...theme.font.heading3, fontWeight: theme.weight.semibold, color: p.color, whiteSpace: "nowrap", animation: `inmuParticle 1.5s cubic-bezier(.15,.7,.3,1) ${p.delay}ms both`, "--dx": `${p.dx}px`, "--dy": `${p.dy}px`, "--rot": `${p.rot}deg` } as unknown as CSSProperties}>{p.ch}</span>
              ))}
            </div>
          ) : null}
        </div>
      </div>

      {g.last ? (
        <div key={g.collapses} style={{ border: `2px dashed ${theme.border.strong}`, borderRadius: 12, overflow: "hidden", background: theme.bg.subtle, animation: "inmuShake 0.6s ease-out" }}>
          <img src={IMG_COLLAPSE} alt="世界崩壊の演出イラスト" style={{ display: "block", width: "100%", aspectRatio: "16 / 6", objectFit: "cover", filter: g.chapter === 2 ? ELDRITCH_FILTER : "none", animation: "inmuZoom 0.9s cubic-bezier(.2,.8,.3,1)" }} />
          <div style={{ padding: 14, display: "flex", gap: 12, alignItems: "flex-start" }}>
            {g.last.img ? <img src={g.last.img} alt={g.last.name} style={{ width: 64, height: 64, objectFit: "cover", borderRadius: 10, border: `1px solid ${theme.border.default}`, flex: "0 0 auto", filter: g.chapter === 2 ? ELDRITCH_FILTER : "none" }} /> : null}
            <div style={{ flex: "1 1 auto", minWidth: 0 }}>
            <div style={{ ...theme.font.label, color: theme.text.tertiary }}>{g.chapter === 1 ? "直近の世界崩壊" : "直近の神性汚染"}{g.last.tile ? `：${g.last.tile}が崩落` : ""}</div>
            <div style={{ ...theme.font.heading3, fontWeight: theme.weight.semibold, marginTop: 4 }}>{g.last.name}</div>
            <div style={sub}>{g.last.desc}</div>
            </div>
          </div>
        </div>
      ) : null}

      <div style={panel}>
        <div style={panelTitle}>戦況パネル</div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 10 }}>
          <div style={{ ...theme.font.label }}>
            <div style={{ color: theme.text.tertiary, marginBottom: 4 }}>敵の行動予測</div>
            <div style={{ color: theme.text.primary }}>{intentOf(g)}</div>
          </div>
          <div style={{ ...theme.font.label }}>
            <div style={{ color: theme.text.tertiary, marginBottom: 4 }}>熱量ゲージ</div>
            <div style={{ display: "flex", gap: 4, marginBottom: 2 }}>
              <span style={{ color: theme.text.primary }}>野獣: {g.p.heat}/{HEAT_MAX}</span>
              <div style={{ flex: 1, background: theme.bg.subtle, borderRadius: 4, overflow: "hidden", height: 16 }}>
                <div style={{ width: `${(g.p.heat / HEAT_MAX) * 100}%`, height: "100%", background: g.p.heat >= HEAT_MAX ? "#ff4444" : "#ffaa00", transition: "width 0.3s" }} />
              </div>
            </div>
            <div style={{ display: "flex", gap: 4 }}>
              <span style={{ color: theme.text.primary }}>敵: {g.c.heat}/{HEAT_MAX}</span>
              <div style={{ flex: 1, background: theme.bg.subtle, borderRadius: 4, overflow: "hidden", height: 16 }}>
                <div style={{ width: `${(g.c.heat / HEAT_MAX) * 100}%`, height: "100%", background: g.c.heat >= HEAT_MAX ? "#ff4444" : "#ffaa00", transition: "width 0.3s" }} />
              </div>
            </div>
          </div>
          <div style={{ ...theme.font.label }}>
            <div style={{ color: theme.text.tertiary, marginBottom: 4 }}>連鎖状態</div>
            <div style={{ color: theme.text.primary }}>
              {g.p.chain >= 2 ? `${g.p.chain}連鎖中（${KIND_LABEL[g.p.chainKind ?? "atk"]}）` : "連鎖なし"}
            </div>
          </div>
          {(() => {
            const afford = g.p.hand.filter((i: Inst) => costOf(g, cardOf(i.key), "p") <= g.p.energy);
            const atk = afford.map((i: Inst) => ({ i, e: estimate(g, i.key) })).filter((x: { i: Inst; e: number }) => x.e > 0).sort((a: { i: Inst; e: number }, b: { i: Inst; e: number }) => b.e - a.e)[0];
            return atk ? (
              <div style={{ ...theme.font.label }}>
                <div style={{ color: theme.text.tertiary, marginBottom: 4 }}>おすすめ札</div>
                <div style={{ color: theme.dataviz.red }}>【{cardOf(atk.i.key).name}】約{atk.e}ダメージ</div>
              </div>
            ) : null;
          })()}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: 12 }}>
        <div style={panel}>
          <div style={panelTitle}>{g.chapter === 1 ? "淫夢マップ" : "汚染エリア"}</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(96px, 1fr))", gap: 6 }}>
            {g.tiles.map((t: Tile) => (
              <div key={t.name} style={{
                ...theme.font.label, padding: "8px 6px", borderRadius: 8, textAlign: "center",
                border: `1px ${t.alive ? "solid" : "dashed"} ${t.alive ? theme.border.default : theme.border.weak}`,
                background: t.alive ? theme.bg.base : "transparent",
                color: t.alive ? theme.text.primary : theme.text.tertiary,
                textDecoration: t.alive ? "none" : "line-through",
                opacity: t.alive ? 1 : 0.55,
              }}>
                {t.alive ? t.name : `${t.name}（崩落）`}
              </div>
            ))}
          </div>
        </div>
        <div style={panel}>
          <div style={panelTitle}>現在の地形・ルール上書き</div>
          {g.mods.length > 0 || g.boost > 0 ? (
            <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
              {g.mods.map((m: Mod) => (
                <span key={m.kind} style={{ ...theme.font.label, border: `1px solid ${theme.border.strong}`, borderRadius: 9999, padding: "3px 10px" }}>
                  {m.label}（残り{m.turns}）
                </span>
              ))}
              {g.boost > 0 ? <span style={{ ...theme.font.label, border: `1px solid ${theme.border.strong}`, borderRadius: 9999, padding: "3px 10px" }}>次の崩壊 +{g.boost}回</span> : null}
            </div>
          ) : (
            <div style={sub}>平常運転（嵐の前の静けさ、本番はこれから）</div>
          )}
          <div style={{ ...theme.font.label, color: theme.text.tertiary, marginTop: 10 }}>
            気力上限 {energyMax(g)}／コスト補正 {costShift(g) > 0 ? `+${costShift(g)}` : costShift(g) < 0 ? String(costShift(g)) : "±0"}
          </div>
          <div style={{ ...theme.font.label, marginTop: 8, borderTop: `1px solid ${theme.border.default}`, paddingTop: 8 }}>
            崩壊予報（ラウンド終了時 ×{nextCount(g)}回）：【{evList(g)[g.fc]?.name ?? "？"}】
          </div>
          <div style={{ ...theme.font.caption, color: theme.text.secondary }}>{evList(g)[g.fc]?.desc ?? ""}</div>
        </div>
      </div>

      <div style={panel}>
        <div style={panelTitle}>あなたの手札（{g.p.hand.length}/{HAND_MAX}）気力 {g.p.energy}</div>
        {g.p.hand.length > 0 ? (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
            {g.p.hand.map((i: Inst) => {
              const d = cardOf(i.key);
              const cost = costOf(g, d, "p");
              const chainHint = g.p.chain > 0 && (g.p.chainKind === d.kind || d.key === "assouda");
              const cut = cost < Math.max(0, d.cost + costShift(g));
              const ok = g.phase === "player" && cost <= g.p.energy;
              const selected = sel === i.uid;
              return (
                <div
                  key={i.uid}
                  role="button"
                  tabIndex={0}
                  onClick={() => pickCard(i.uid)}
                  onKeyDown={(e: KeyboardEvent<HTMLDivElement>) => onCardKey(e, i.uid)}
                  style={{
                    flex: "1 1 170px", maxWidth: 260, borderRadius: 12, overflow: "hidden",
                    border: `${selected ? 3 : 2}px solid transparent`,
                    background: `linear-gradient(170deg, color-mix(in srgb, ${kindColor(d.kind)} 20%, ${theme.bg.base}), ${theme.bg.base} 55%) padding-box, linear-gradient(135deg, #fff3b0, #e0a800 25%, #8a5a00 50%, #ffd84a 75%, #fff3b0) border-box`, cursor: g.phase === "player" ? "pointer" : "default",
                    opacity: ok || g.phase !== "player" ? 1 : 0.5, transition: theme.motion.hover,
                    transform: selected ? "translateY(-6px) scale(1.04)" : "none",
                    boxShadow: chainHint && ok ? `0 0 0 2px ${kindColor(d.kind)}, 0 0 22px ${kindColor(d.kind)}` : selected ? "0 0 0 1px #ffd84a, 0 0 24px rgba(255,200,60,0.7), 0 10px 20px rgba(0,0,0,0.4)" : "0 4px 12px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.12)",
                    animation: "drawFlash 0.5s ease-out",
                  }}
                >
                  {CARD_ART[d.key] ? <div style={{ height: 72, backgroundImage: `linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.55)), url(${CARD_ART[d.key]})`, backgroundSize: "cover", backgroundPosition: "center 30%", borderBottom: `3px solid ${kindColor(d.kind)}` }} /> : <div style={{ height: 8, background: `linear-gradient(90deg, ${kindColor(d.kind)}, #ffd84a, ${kindColor(d.kind)})`, boxShadow: `0 0 10px ${kindColor(d.kind)}` }} />}
                  <div style={{ padding: 10, display: "flex", flexDirection: "column", gap: 4 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 6 }}>
                      <span style={{ ...theme.font.label, color: theme.text.tertiary, display: "inline-flex", alignItems: "center", gap: 6 }}>
                        <KindIcon kind={d.kind} size={CARD_ART[d.key] ? 32 : 26} art={CARD_ART[d.key]} />
                        {KIND_LABEL[d.kind]}
                      </span>
                      <span style={{ ...theme.font.label, fontWeight: theme.weight.semibold }}>{chainHint ? `${g.p.chain + 1}連鎖！ ` : ""}気力{cost}{cut ? "↓" : ""}</span>
                    </div>
                    <div style={{ ...theme.font.body2, fontWeight: 900, textShadow: `0 0 8px color-mix(in srgb, ${kindColor(d.kind)} 70%, transparent)` }}>{d.name}</div>
                    <div style={{ ...theme.font.label, color: theme.text.secondary }}>{has(g, "nameless") ? "？？？（名状しがたい効果）" : d.text}</div>
                    {CARD_TIPS[d.key] ? <div style={{ ...theme.font.caption, color: theme.text.secondary }}>戦術：{CARD_TIPS[d.key]}</div> : null}
                    <div style={{ ...theme.font.caption, color: theme.text.tertiary }}>{d.flavor}</div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div style={sub}>手札が全部消えた。ファッ！？ パスして引き直そう（しょうがねぇなぁ）</div>
        )}
        {g.phase === "player" ? (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8, alignItems: "center", marginTop: 12 }}>
            <button disabled={!selPlayable} onClick={playSelected} style={{padding:"10px 20px",background:"#d4af37",color:"#1a1511",border:"none",borderRadius:"4px",fontSize:"18px",fontWeight:"bold",cursor:"pointer"}}>{selDef ? `【${selDef.name}】を出す` : "カードを選んでね（あくしろよ）"}</button>
            <button onClick={pass} aria-label="ターン終了" style={{padding:"8px 16px",background:"#666",color:"#fff",border:"none",borderRadius:"4px",cursor:"pointer"}}>{g.p.played === 0 ? "ターン終了（パス：1枚ドロー＋HP3＋熱量1）" : g.p.energy > 0 ? "ターン終了（余り気力→熱量+1）" : "ターン終了"}</button>
            <button disabled={g.p.heat < 3} onClick={() => heatAct("kiai")} style={{padding:"8px 16px",background:"#666",color:"#fff",border:"none",borderRadius:"4px",cursor:"pointer"}}>迫真の気合（熱量3→気力+1）</button>
            <button disabled={g.p.heat < HEAT_MAX || g.p.awaken} onClick={() => heatAct("awaken")} style={{padding:"8px 16px",background:"#666",color:"#fff",border:"none",borderRadius:"4px",cursor:"pointer"}}>野獣覚醒（熱量5→次の攻撃×2・貫通）</button>
            {selDef && !selPlayable ? <span style={{ ...theme.font.label, color: theme.text.warning }}>気力が足りない（そんな装備で大丈夫か？）</span> : null}
          </div>
        ) : null}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: 12 }}>
        <div style={panel}>
          <div style={panelTitle}>崩壊ログ</div>
          <div style={{ maxHeight: 280, overflowY: "auto", display: "flex", flexDirection: "column", gap: 4 }}>
            {g.clog.map((l: LogLine) => (
              <div key={l.id} style={{ ...theme.font.label, color: l.text.startsWith("└") ? theme.text.secondary : theme.text.primary, borderLeft: `3px solid ${theme.dataviz.other}`, paddingLeft: 8 }}>{l.text}</div>
            ))}
          </div>
        </div>
        <div style={panel}>
          <div style={panelTitle}>バトルログ</div>
          <div style={{ maxHeight: 280, overflowY: "auto", display: "flex", flexDirection: "column", gap: 4 }}>
            {g.log.map((l: LogLine) => (
              <div key={l.id} style={{ ...theme.font.label, color: l.who === "sys" ? theme.text.tertiary : theme.text.primary, borderLeft: `3px solid ${whoColor(l.who)}`, paddingLeft: 8 }}>{l.text}</div>
            ))}
          </div>
        </div>
      </div>

      {g.phase !== "end" ? (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
          <button onClick={retry} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"16px",fontWeight:"bold",cursor:"pointer"}}>このバトルをやり直す</button>
          <button onClick={toTitle} style={{background:theme.accent,color:theme.bg,border:"none",padding:"8px 16px",borderRadius:"4px",fontSize:"16px",fontWeight:"bold",cursor:"pointer"}}>タイトルへ</button>
        </div>
      ) : null}
    </div>
  );
}
